-- ======== PG-SCHEMA-001  P5  Sequence or integer key at 90 percent or more of its range ========
SELECT (current_setting('server_version_num')::int >= 100000) AS gate_pg_schema_001 \gset
\if :gate_pg_schema_001
\echo '@@CHECK PG-SCHEMA-001'
-- check: PG-SCHEMA-001
-- title: Sequence or integer key at 90 percent or more of its range
-- priority: 5
-- scope: relation
-- cost: 1
-- min_version: 10
-- thresholds: exhaustion_fraction
WITH owned AS (
  SELECT s.schemaname, s.sequencename, s.last_value, s.max_value, s.min_value,
         s.increment_by, s.cycle,
         a.attname AS owner_column, tn.nspname AS owner_schema, tc.relname AS owner_table,
         t.typname AS owner_type,
         CASE t.typname WHEN 'int2' THEN 32767::bigint
                        WHEN 'int4' THEN 2147483647::bigint
                        WHEN 'int8' THEN 9223372036854775807::bigint
                        ELSE NULL END AS type_max
  FROM pg_sequences s
  JOIN pg_class sc      ON sc.relname = s.sequencename
  JOIN pg_namespace sn  ON sn.oid = sc.relnamespace AND sn.nspname = s.schemaname
  LEFT JOIN pg_depend d ON d.objid = sc.oid AND d.classid = 'pg_class'::regclass
                        AND d.refclassid = 'pg_class'::regclass AND d.deptype IN ('a', 'i')
  LEFT JOIN pg_class tc     ON tc.oid = d.refobjid
  LEFT JOIN pg_namespace tn ON tn.oid = tc.relnamespace
  LEFT JOIN pg_attribute a  ON a.attrelid = d.refobjid AND a.attnum = d.refobjsubid
  LEFT JOIN pg_type t       ON t.oid = a.atttypid
  WHERE sc.relkind = 'S'
),
scored AS (
  SELECT o.*, least(o.max_value, coalesce(o.type_max, o.max_value)) AS effective_max,
         o.last_value::numeric / nullif(least(o.max_value, coalesce(o.type_max, o.max_value)), 0)::numeric AS used_fraction
  FROM owned o WHERE o.last_value IS NOT NULL AND o.increment_by > 0 AND NOT o.cycle
)
SELECT 'PG-SCHEMA-001'::text AS check_id,
       'relation'::text AS scope,
       format('%I.%I.%I', current_database(), s.schemaname, s.sequencename)::text AS object,
       format('Sequence %s.%s is at %s of an effective maximum of %s (%s%%, threshold %s%%). %s When it runs out, every INSERT that calls nextval fails: "nextval: reached maximum value of sequence" or, if the column type is the binding limit, "integer out of range". Widening the column to bigint rewrites the whole table and every index on it, which is why this is worth seeing at 70%% rather than at 99%%.',
              s.schemaname, s.sequencename,
              to_char(s.last_value, 'FM999,999,999,999,999,999'),
              to_char(s.effective_max, 'FM999,999,999,999,999,999'),
              round(100 * s.used_fraction, 1)::text,
              round(100 * :'pg_schema_001_exhaustion_fraction'::numeric)::text,
              CASE WHEN s.owner_table IS NULL
                   THEN 'It is not owned by any column, so the limit is the sequence''s own max_value.'
                   ELSE format('It backs %s.%s.%s of type %s, whose maximum (%s) %s the sequence''s own max_value (%s).',
                               s.owner_schema, s.owner_table, s.owner_column, s.owner_type,
                               to_char(s.type_max, 'FM999,999,999,999,999,999'),
                               CASE WHEN s.type_max < s.max_value THEN 'is lower than' ELSE 'is not lower than' END,
                               to_char(s.max_value, 'FM999,999,999,999,999,999')) END) AS details,
       json_build_object('schema', s.schemaname, 'sequence', s.sequencename,
                         'last_value', s.last_value, 'max_value', s.max_value,
                         'effective_max', s.effective_max,
                         'used_fraction', round(s.used_fraction, 5),
                         'threshold_fraction', :'pg_schema_001_exhaustion_fraction'::numeric,
                         'increment_by', s.increment_by,
                         'owner_schema', s.owner_schema, 'owner_table', s.owner_table,
                         'owner_column', s.owner_column, 'owner_type', s.owner_type)::text AS evidence_json,
       'high'::text AS confidence
FROM scored s
WHERE s.used_fraction >= :'pg_schema_001_exhaustion_fraction'::numeric
ORDER BY s.used_fraction DESC;
\echo '@@END PG-SCHEMA-001'
\else
\echo '@@SKIP PG-SCHEMA-001 needs PostgreSQL 10 or newer'
\endif

-- ======== PG-REPL-013  P10  Published table without a usable replica identity ========
SELECT (current_setting('server_version_num')::int >= 100000 AND NOT pg_is_in_recovery()) AS gate_pg_repl_013 \gset
\if :gate_pg_repl_013
\echo '@@CHECK PG-REPL-013'
-- check: PG-REPL-013
-- title: Published table without a usable replica identity
-- priority: 10
-- scope: relation
-- cost: 1
-- min_version: 10
-- run_on: primary
SELECT 'PG-REPL-013'::text AS check_id,
       'relation'::text    AS scope,
       format('%I.%I.%I', current_database(), pt.schemaname, pt.tablename)::text AS object,
       format('Table %s.%s is published by %s for UPDATE and/or DELETE but its REPLICA IDENTITY is %s. UPDATE and DELETE against it raise "cannot update table ... because it does not have a replica identity and publishes updates" and the statement fails. Set a primary key, or ALTER TABLE %s.%s REPLICA IDENTITY USING INDEX <a unique, non-partial, NOT NULL index>, or as a last resort REPLICA IDENTITY FULL (which ships the whole old row: see PG-SCHEMA-004).',
              pt.schemaname, pt.tablename, p.pubname,
              CASE c.relreplident WHEN 'n' THEN 'NOTHING'
                                  WHEN 'd' THEN 'DEFAULT with no primary key'
                                  WHEN 'i' THEN 'USING INDEX but no valid replica-identity index exists'
                                  ELSE c.relreplident::text END,
              quote_ident(pt.schemaname), quote_ident(pt.tablename)) AS details,
       json_build_object('schema', pt.schemaname, 'table', pt.tablename,
                         'publication', p.pubname, 'relreplident', c.relreplident::text,
                         'pubupdate', p.pubupdate, 'pubdelete', p.pubdelete,
                         'has_primary_key', EXISTS (SELECT 1 FROM pg_index i WHERE i.indrelid = c.oid AND i.indisprimary AND i.indisvalid),
                         'total_bytes', pg_total_relation_size(c.oid))::text AS evidence_json,
       'high'::text AS confidence
FROM pg_publication_tables pt
JOIN pg_publication p  ON p.pubname = pt.pubname
JOIN pg_namespace n    ON n.nspname = pt.schemaname
JOIN pg_class c        ON c.relname = pt.tablename AND c.relnamespace = n.oid
WHERE (p.pubupdate OR p.pubdelete)
  AND (c.relreplident = 'n'
    OR (c.relreplident = 'd'
        AND NOT EXISTS (SELECT 1 FROM pg_index i WHERE i.indrelid = c.oid AND i.indisprimary AND i.indisvalid))
    OR (c.relreplident = 'i'
        AND NOT EXISTS (SELECT 1 FROM pg_index i WHERE i.indrelid = c.oid AND i.indisreplident AND i.indisvalid)));
\echo '@@END PG-REPL-013'
\else
\echo '@@SKIP PG-REPL-013 needs PostgreSQL 10 or newer; primary only'
\endif

-- ======== PG-IDX-001  P50  Invalid index ========
\echo '@@CHECK PG-IDX-001'
-- check: PG-IDX-001
-- title: Invalid index
-- priority: 50
-- scope: index
-- cost: 1
SELECT 'PG-IDX-001'::text AS check_id,
       'index'::text      AS scope,
       format('%I.%I.%I', current_database(), n.nspname, ic.relname)::text AS object,
       format('Index %s on %s.%s is %s. It is still maintained on every insert, update and delete of the table, it is never used by the planner, and %s Size %s against a table of %s. Definition: %s. This is almost always the debris of a CREATE INDEX CONCURRENTLY that failed or was interrupted. Fix: REINDEX INDEX CONCURRENTLY %s.%s on PostgreSQL 12 and newer, or DROP INDEX CONCURRENTLY and recreate it.',
              ic.relname, n.nspname, tc.relname,
              CASE WHEN NOT i.indisready THEN 'not ready (indisready = false, so it is not even receiving new entries)'
                   ELSE 'invalid (indisvalid = false)' END,
              CASE WHEN i.indisunique
                   THEN 'because it is unique it still rejects conflicting inserts, so it changes behaviour without providing any benefit.'
                   ELSE 'it provides nothing in return.' END,
              pg_size_pretty(pg_relation_size(i.indexrelid)),
              pg_size_pretty(pg_relation_size(i.indrelid)),
              pg_get_indexdef(i.indexrelid),
              quote_ident(n.nspname), quote_ident(ic.relname)) AS details,
       json_build_object('schema', n.nspname, 'table', tc.relname, 'index', ic.relname,
                         'indisvalid', i.indisvalid, 'indisready', i.indisready,
                         'indisunique', i.indisunique, 'indisprimary', i.indisprimary,
                         'index_bytes', pg_relation_size(i.indexrelid),
                         'table_bytes', pg_relation_size(i.indrelid),
                         'indexdef', pg_get_indexdef(i.indexrelid))::text AS evidence_json,
       'high'::text AS confidence
FROM pg_index i
JOIN pg_class ic     ON ic.oid = i.indexrelid
JOIN pg_class tc     ON tc.oid = i.indrelid
JOIN pg_namespace n  ON n.oid = ic.relnamespace
WHERE (NOT i.indisvalid OR NOT i.indisready)
  AND n.nspname NOT IN ('pg_catalog', 'information_schema', 'pg_toast')
ORDER BY pg_relation_size(i.indexrelid) DESC;
\echo '@@END PG-IDX-001'

-- ======== PG-IDX-002  P50  Unused index 1 GB or larger ========
SELECT (NOT pg_is_in_recovery()) AS gate_pg_idx_002 \gset
\if :gate_pg_idx_002
\echo '@@CHECK PG-IDX-002'
-- check: PG-IDX-002
-- title: Unused index 1 GB or larger
-- priority: 50
-- scope: index
-- cost: 1
-- thresholds: min_bytes, stats_age_days
WITH win AS (
  SELECT greatest(extract(epoch FROM now() - coalesce(
           (SELECT min(stats_reset) FROM pg_stat_database WHERE datname = current_database()),
           pg_postmaster_start_time())) / 86400.0, 0.01) AS days
)
SELECT 'PG-IDX-002'::text AS check_id,
       'index'::text    AS scope,
       format('%I.%I.%I', current_database(), s.schemaname, s.indexrelname)::text AS object,
       format('Index %s on %s.%s has been scanned 0 times in %s days of collected statistics (threshold: size >= %s%s). Size %s, table %s, %s writes to the table since the reset - every one of those maintained this index for nothing. Definition: %s. Usage counters are per instance: an index unused here may be serving a read replica, so verify on every standby before dropping. The reversible first step is ALTER INDEX %s.%s SET (deprecated) - there is no such option, so in practice: drop it in a transaction you are prepared to roll back, or rename it and watch for errors, then DROP INDEX CONCURRENTLY.',
              s.indexrelname, s.schemaname, s.relname,
              round(w.days, 1)::text,
              pg_size_pretty(:'pg_idx_002_min_bytes'::bigint), ' and statistics at least 30 days old',
              pg_size_pretty(pg_relation_size(s.indexrelid)),
              pg_size_pretty(pg_relation_size(s.relid)),
              to_char(coalesce(t.n_tup_ins + t.n_tup_upd + t.n_tup_del, 0), 'FM999,999,999,999'),
              pg_get_indexdef(s.indexrelid),
              quote_ident(s.schemaname), quote_ident(s.indexrelname)) AS details,
       json_build_object('schema', s.schemaname, 'table', s.relname, 'index', s.indexrelname,
                         'idx_scan', s.idx_scan,
                         'index_bytes', pg_relation_size(s.indexrelid),
                         'table_bytes', pg_relation_size(s.relid),
                         'threshold_bytes', :'pg_idx_002_min_bytes'::bigint,
                         'stats_window_days', round(w.days, 2),
                         'table_writes', coalesce(t.n_tup_ins + t.n_tup_upd + t.n_tup_del, 0),
                         'indexdef', pg_get_indexdef(s.indexrelid),
                         'indisunique', i.indisunique, 'indisprimary', i.indisprimary)::text AS evidence_json,
       'medium'::text AS confidence
FROM pg_stat_user_indexes s
JOIN pg_index i           ON i.indexrelid = s.indexrelid
LEFT JOIN pg_stat_user_tables t ON t.relid = s.relid
CROSS JOIN win w
WHERE s.idx_scan = 0
  AND NOT i.indisunique AND NOT i.indisprimary AND NOT i.indisreplident
  AND i.indisvalid
  AND NOT EXISTS (SELECT 1 FROM pg_constraint con WHERE con.conindid = s.indexrelid)
  AND pg_relation_size(s.indexrelid) >= :'pg_idx_002_min_bytes'::bigint
  AND w.days >= :'pg_idx_002_stats_age_days'::numeric
ORDER BY pg_relation_size(s.indexrelid) DESC
LIMIT 50;
\echo '@@END PG-IDX-002'
\else
\echo '@@SKIP PG-IDX-002 primary only'
\endif

-- ======== PG-IDX-004  P50  Duplicate indexes ========
\echo '@@CHECK PG-IDX-004'
-- check: PG-IDX-004
-- title: Duplicate indexes
-- priority: 50
-- scope: index
-- cost: 1
WITH sig AS (
  SELECT i.indexrelid, i.indrelid,
         n.nspname, tc.relname AS table_name, ic.relname AS index_name,
         pg_relation_size(i.indexrelid) AS index_bytes,
         s.idx_scan,
         i.indisunique, i.indisprimary,
         EXISTS (SELECT 1 FROM pg_constraint con WHERE con.conindid = i.indexrelid) AS backs_constraint,
         format('%s|%s|%s|%s|%s|%s|%s',
                ic.relam, i.indkey::text, i.indclass::text, i.indoption::text,
                coalesce(pg_get_expr(i.indexprs, i.indrelid), ''),
                coalesce(pg_get_expr(i.indpred, i.indrelid), ''),
                i.indisunique) AS signature
  FROM pg_index i
  JOIN pg_class ic    ON ic.oid = i.indexrelid
  JOIN pg_class tc    ON tc.oid = i.indrelid
  JOIN pg_namespace n ON n.oid = ic.relnamespace
  LEFT JOIN pg_stat_user_indexes s ON s.indexrelid = i.indexrelid
  WHERE i.indisvalid
    AND n.nspname NOT IN ('pg_catalog', 'information_schema', 'pg_toast')
),
grp AS (
  SELECT indrelid, nspname, table_name, signature, count(*) AS n,
         sum(index_bytes) AS total_bytes,
         string_agg(format('%s (%s, %s scans%s)', index_name, pg_size_pretty(index_bytes),
                           coalesce(idx_scan::text, 'unknown'),
                           CASE WHEN backs_constraint THEN ', backs a constraint' ELSE '' END),
                    '; ' ORDER BY backs_constraint DESC, index_bytes DESC) AS members,
         (array_agg(index_name ORDER BY backs_constraint DESC, idx_scan DESC NULLS LAST, index_bytes DESC))[1] AS keeper
  FROM sig GROUP BY 1, 2, 3, 4 HAVING count(*) > 1
)
SELECT 'PG-IDX-004'::text AS check_id,
       'index'::text      AS scope,
       format('%I.%I.%I', current_database(), g.nspname, g.table_name)::text AS object,
       format('%s indexes on %s.%s are identical in every catalog column that determines what an index can answer - access method, key columns, operator classes, sort options, expression, predicate and uniqueness: %s. Together they occupy %s and every write to the table maintains all of them. Keep %s (it backs a constraint or has the most recorded use) and drop the rest with DROP INDEX CONCURRENTLY. Usage counters are per instance: check the standbys first.',
              g.n, g.nspname, g.table_name, g.members,
              pg_size_pretty(g.total_bytes), g.keeper) AS details,
       json_build_object('schema', g.nspname, 'table', g.table_name,
                         'duplicate_count', g.n, 'total_bytes', g.total_bytes,
                         'members', g.members, 'suggested_keeper', g.keeper,
                         'signature', g.signature)::text AS evidence_json,
       'high'::text AS confidence
FROM grp g
ORDER BY g.total_bytes DESC;
\echo '@@END PG-IDX-004'

-- ======== PG-IDX-006  P50  Estimated B-tree bloat over 50 percent (500 MB or more wasted) ========
\echo '@@CHECK PG-IDX-006'
-- check: PG-IDX-006
-- title: Estimated B-tree bloat over 50 percent (500 MB or more wasted)
-- priority: 50
-- scope: index
-- cost: 1
-- thresholds: bloat_pct, wasted_bytes, top_n
-- estimator: lib/bloat_btree.sql (re-derived from documented page layout; no third-party code)
WITH const AS (
  SELECT current_setting('block_size')::numeric AS bs,
         8::numeric AS index_tuple_hdr, 8::numeric AS ma,
         24::numeric AS page_hdr, 16::numeric AS btree_special, 4::numeric AS item_id
),
idx AS (
  SELECT i.indexrelid, i.indrelid, ic.relname AS index_name, tn.nspname, tc.relname AS table_name,
         ic.reltuples::numeric AS reltuples, ic.relpages::numeric AS relpages,
         pg_relation_size(i.indexrelid) AS index_bytes,
         i.indnatts, i.indnkeyatts, i.indkey,
         (i.indexprs IS NOT NULL OR i.indpred IS NOT NULL) AS is_special,
         coalesce(substring(array_to_string(ic.reloptions, ' ') FROM 'fillfactor=([0-9]+)')::numeric, 90) AS fillfactor
  FROM pg_index i
  JOIN pg_class ic ON ic.oid = i.indexrelid
  JOIN pg_class tc ON tc.oid = i.indrelid
  JOIN pg_namespace tn ON tn.oid = tc.relnamespace
  JOIN pg_am am ON am.oid = ic.relam AND am.amname = 'btree'
  WHERE tn.nspname NOT IN ('pg_catalog', 'information_schema', 'pg_toast')
    AND i.indisvalid
),
keywidth AS (
  SELECT x.indexrelid,
         sum((1 - s.null_frac)::numeric * s.avg_width)    AS keywidth,
         count(*) FILTER (WHERE s.null_frac > 0) AS nullable_cols,
         count(*)                                AS ncols
  FROM (SELECT idx.indexrelid, idx.nspname, idx.table_name, a.attname
        FROM idx
        JOIN LATERAL unnest(idx.indkey[0:idx.indnkeyatts - 1]) WITH ORDINALITY AS k(attnum, ord) ON true
        JOIN pg_attribute a ON a.attrelid = idx.indrelid AND a.attnum = k.attnum
        WHERE NOT idx.is_special) x
  JOIN pg_stats s ON s.schemaname = x.nspname AND s.tablename = x.table_name AND s.attname = x.attname
  GROUP BY 1
),
est AS (
  SELECT idx.*, const.bs,
         ceil((const.index_tuple_hdr + CASE WHEN kw.nullable_cols > 0 THEN ceil(kw.ncols / 8.0) ELSE 0 END) / const.ma) * const.ma
           + ceil(coalesce(kw.keywidth, 0) / const.ma) * const.ma AS entry_bytes,
         greatest(1, floor(((const.bs - const.page_hdr - const.btree_special) * idx.fillfactor / 100.0)
                  / (ceil((const.index_tuple_hdr + CASE WHEN kw.nullable_cols > 0 THEN ceil(kw.ncols / 8.0) ELSE 0 END) / const.ma) * const.ma
                     + ceil(coalesce(kw.keywidth, 0) / const.ma) * const.ma + const.item_id))) AS entries_per_page,
         (idx.is_special OR kw.keywidth IS NULL OR idx.reltuples < 0 OR idx.relpages <= 1) AS is_na
  FROM idx LEFT JOIN keywidth kw ON kw.indexrelid = idx.indexrelid CROSS JOIN const
),
scored AS (
  SELECT nspname, table_name, index_name, reltuples, relpages, index_bytes, fillfactor,
         entry_bytes, entries_per_page,
         greatest(relpages - ceil(reltuples / entries_per_page), 0) AS bloat_pages,
         (greatest(relpages - ceil(reltuples / entries_per_page), 0) * bs)::bigint AS bloat_bytes,
         round(100.0 * greatest(relpages - ceil(reltuples / entries_per_page), 0) / nullif(relpages, 0), 1) AS bloat_pct
  FROM est WHERE NOT is_na
)
SELECT 'PG-IDX-006'::text AS check_id,
       'index'::text     AS scope,
       format('%I.%I.%I', current_database(), s.nspname, s.index_name)::text AS object,
       format('Estimated %s%% bloat (threshold %s%%) on index %s of table %s: %s of %s is not occupied by live entries, against %s estimated entries at %s bytes each and fillfactor %s. Estimated from pg_stats and pg_class only. REINDEX INDEX CONCURRENTLY rebuilds it without blocking writes on PostgreSQL 12 and newer.',
              s.bloat_pct::text, :'pg_idx_006_bloat_pct'::text, s.index_name, s.table_name,
              pg_size_pretty(s.bloat_bytes), pg_size_pretty(s.index_bytes),
              to_char(s.reltuples::bigint, 'FM999,999,999,999'), s.entry_bytes::text, s.fillfactor::text) AS details,
       json_build_object('bloat_pct', s.bloat_pct, 'bloat_bytes', s.bloat_bytes,
                         'index_bytes', s.index_bytes, 'relpages', s.relpages::bigint,
                         'reltuples', s.reltuples::bigint, 'estimated_entry_bytes', s.entry_bytes,
                         'fillfactor', s.fillfactor, 'table', s.table_name,
                         'threshold_pct', :'pg_idx_006_bloat_pct'::numeric,
                         'threshold_wasted_bytes', :'pg_idx_006_wasted_bytes'::bigint,
                         'estimator', 'lib/bloat_btree.sql')::text AS evidence_json,
       'medium'::text AS confidence
FROM scored s
WHERE s.bloat_pct   >= :'pg_idx_006_bloat_pct'::numeric
  AND s.bloat_bytes >= :'pg_idx_006_wasted_bytes'::bigint
ORDER BY s.bloat_bytes DESC
LIMIT :'pg_idx_006_top_n'::int;
\echo '@@END PG-IDX-006'

-- ======== PG-IDX-008  P50  Unindexed foreign key on a large table ========
\echo '@@CHECK PG-IDX-008'
-- check: PG-IDX-008
-- title: Unindexed foreign key on a large table
-- priority: 50
-- scope: relation
-- cost: 1
-- thresholds: min_bytes, parent_writes
WITH fk AS (
  SELECT con.oid AS conoid, con.conname, con.conrelid, con.confrelid, con.conkey,
         cn.nspname AS child_schema, cc.relname AS child_table,
         pn.nspname AS parent_schema, pc.relname AS parent_table,
         pg_relation_size(con.conrelid) AS child_bytes,
         coalesce(pt.n_tup_del + pt.n_tup_upd, 0) AS parent_writes,
         (SELECT string_agg(a.attname, ', ' ORDER BY k.ord)
          FROM unnest(con.conkey) WITH ORDINALITY AS k(attnum, ord)
          JOIN pg_attribute a ON a.attrelid = con.conrelid AND a.attnum = k.attnum) AS child_columns
  FROM pg_constraint con
  JOIN pg_class cc      ON cc.oid = con.conrelid
  JOIN pg_namespace cn  ON cn.oid = cc.relnamespace
  JOIN pg_class pc      ON pc.oid = con.confrelid
  JOIN pg_namespace pn  ON pn.oid = pc.relnamespace
  LEFT JOIN pg_stat_user_tables pt ON pt.relid = con.confrelid
  WHERE con.contype = 'f'
    AND cn.nspname NOT IN ('pg_catalog', 'information_schema', 'pg_toast')
),
unindexed AS (
  SELECT fk.* FROM fk
  WHERE NOT EXISTS (
    SELECT 1 FROM pg_index i
    WHERE i.indrelid = fk.conrelid AND i.indisvalid
      AND (string_to_array(i.indkey::text, ' '))[1:cardinality(fk.conkey)]
          = (SELECT array_agg(x::text ORDER BY o) FROM unnest(fk.conkey) WITH ORDINALITY AS u(x, o))
  )
)
SELECT 'PG-IDX-008'::text AS check_id,
       'relation'::text AS scope,
       format('%I.%I.%I', current_database(), u.child_schema, u.child_table)::text AS object,
       format('Foreign key %s on %s.%s (%s) references %s.%s and has no index whose leading columns match it. Child table %s, parent has had %s updates and deletes since the statistics reset. Every DELETE or key UPDATE on the parent has to sequentially scan the child under a lock to check the constraint, and ON DELETE CASCADE makes that scan happen per parent row. Thresholds: child size >= %s or parent writes >= %s. Fix: CREATE INDEX CONCURRENTLY ON %s.%s (%s).',
              u.conname, u.child_schema, u.child_table, u.child_columns,
              u.parent_schema, u.parent_table,
              pg_size_pretty(u.child_bytes),
              to_char(u.parent_writes, 'FM999,999,999,999'),
              pg_size_pretty(:'pg_idx_008_min_bytes'::bigint),
              to_char(:'pg_idx_008_parent_writes'::bigint, 'FM999,999,999,999'),
              quote_ident(u.child_schema), quote_ident(u.child_table), u.child_columns) AS details,
       json_build_object('constraint', u.conname,
                         'child_schema', u.child_schema, 'child_table', u.child_table,
                         'child_columns', u.child_columns,
                         'parent_schema', u.parent_schema, 'parent_table', u.parent_table,
                         'child_bytes', u.child_bytes, 'parent_writes', u.parent_writes,
                         'threshold_child_bytes', :'pg_idx_008_min_bytes'::bigint,
                         'threshold_parent_writes', :'pg_idx_008_parent_writes'::bigint)::text AS evidence_json,
       'high'::text AS confidence
FROM unindexed u
WHERE u.child_bytes >= :'pg_idx_008_min_bytes'::bigint
     OR u.parent_writes >= :'pg_idx_008_parent_writes'::bigint
ORDER BY u.child_bytes DESC;
\echo '@@END PG-IDX-008'

-- ======== PG-IDX-010  P50  Large table with heavy sequential scans ========
\echo '@@CHECK PG-IDX-010'
-- check: PG-IDX-010
-- title: Large table with heavy sequential scans
-- priority: 50
-- scope: relation
-- cost: 1
-- thresholds: min_bytes, min_seq_scans, rows_per_scan, seq_fraction, top_n
SELECT 'PG-IDX-010'::text AS check_id,
       'relation'::text AS scope,
       format('%I.%I.%I', current_database(), t.schemaname, t.relname)::text AS object,
       format('Table %s.%s (%s) has had %s sequential scans and %s index scans since the statistics reset, reading an average of %s rows per sequential scan. Sequential scans are %s%% of all scans (thresholds: size %s, %s scans, %s rows per scan, %s%% of scans). Something queries this table without a usable index, or with a predicate the planner cannot use. Confidence is medium: a nightly export or an analytics job legitimately reads the whole table, and this counter cannot tell those apart from a missing index. PG-QRY-003 and PG-QRY-005 show which statements dominate.',
              t.schemaname, t.relname,
              pg_size_pretty(pg_relation_size(t.relid)),
              to_char(t.seq_scan, 'FM999,999,999,999'),
              to_char(coalesce(t.idx_scan, 0), 'FM999,999,999,999'),
              to_char(round(t.seq_tup_read::numeric / nullif(t.seq_scan, 0)), 'FM999,999,999,999'),
              round(100.0 * t.seq_scan / nullif(t.seq_scan + coalesce(t.idx_scan, 0), 0), 1)::text,
              pg_size_pretty(:'pg_idx_010_min_bytes'::bigint),
              :'pg_idx_010_min_seq_scans'::text,
              to_char(:'pg_idx_010_rows_per_scan'::bigint, 'FM999,999,999,999'),
              round(100 * :'pg_idx_010_seq_fraction'::numeric)::text) AS details,
       json_build_object('schema', t.schemaname, 'table', t.relname,
                         'seq_scan', t.seq_scan, 'idx_scan', coalesce(t.idx_scan, 0),
                         'seq_tup_read', t.seq_tup_read,
                         'rows_per_seq_scan', round(t.seq_tup_read::numeric / nullif(t.seq_scan, 0))::bigint,
                         'seq_fraction', round(t.seq_scan::numeric / nullif(t.seq_scan + coalesce(t.idx_scan, 0), 0), 4),
                         'relation_bytes', pg_relation_size(t.relid),
                         'index_count', (SELECT count(*) FROM pg_index i WHERE i.indrelid = t.relid),
                         'threshold_bytes', :'pg_idx_010_min_bytes'::bigint,
                         'threshold_seq_scans', :'pg_idx_010_min_seq_scans'::bigint,
                         'threshold_rows_per_scan', :'pg_idx_010_rows_per_scan'::bigint,
                         'threshold_seq_fraction', :'pg_idx_010_seq_fraction'::numeric)::text AS evidence_json,
       'medium'::text AS confidence
FROM pg_stat_user_tables t
WHERE pg_relation_size(t.relid) >= :'pg_idx_010_min_bytes'::bigint
  AND t.seq_scan >= :'pg_idx_010_min_seq_scans'::bigint
  AND t.seq_tup_read::numeric / nullif(t.seq_scan, 0) >= :'pg_idx_010_rows_per_scan'::bigint
  AND t.seq_scan::numeric / nullif(t.seq_scan + coalesce(t.idx_scan, 0), 0) >= :'pg_idx_010_seq_fraction'::numeric
ORDER BY t.seq_tup_read DESC
LIMIT :'pg_idx_010_top_n'::int;
\echo '@@END PG-IDX-010'

-- ======== PG-SCHEMA-002  P50  Sequence or integer key at 70 percent or more of its range ========
SELECT (current_setting('server_version_num')::int >= 100000) AS gate_pg_schema_002 \gset
\if :gate_pg_schema_002
\echo '@@CHECK PG-SCHEMA-002'
-- check: PG-SCHEMA-002
-- title: Sequence or integer key at 70 percent or more of its range
-- priority: 50
-- scope: relation
-- cost: 1
-- min_version: 10
-- thresholds: exhaustion_fraction, exhaustion_fraction_high
WITH owned AS (
  SELECT s.schemaname, s.sequencename, s.last_value, s.max_value, s.min_value,
         s.increment_by, s.cycle,
         a.attname AS owner_column, tn.nspname AS owner_schema, tc.relname AS owner_table,
         t.typname AS owner_type,
         CASE t.typname WHEN 'int2' THEN 32767::bigint
                        WHEN 'int4' THEN 2147483647::bigint
                        WHEN 'int8' THEN 9223372036854775807::bigint
                        ELSE NULL END AS type_max
  FROM pg_sequences s
  JOIN pg_class sc      ON sc.relname = s.sequencename
  JOIN pg_namespace sn  ON sn.oid = sc.relnamespace AND sn.nspname = s.schemaname
  LEFT JOIN pg_depend d ON d.objid = sc.oid AND d.classid = 'pg_class'::regclass
                        AND d.refclassid = 'pg_class'::regclass AND d.deptype IN ('a', 'i')
  LEFT JOIN pg_class tc     ON tc.oid = d.refobjid
  LEFT JOIN pg_namespace tn ON tn.oid = tc.relnamespace
  LEFT JOIN pg_attribute a  ON a.attrelid = d.refobjid AND a.attnum = d.refobjsubid
  LEFT JOIN pg_type t       ON t.oid = a.atttypid
  WHERE sc.relkind = 'S'
),
scored AS (
  SELECT o.*, least(o.max_value, coalesce(o.type_max, o.max_value)) AS effective_max,
         o.last_value::numeric / nullif(least(o.max_value, coalesce(o.type_max, o.max_value)), 0)::numeric AS used_fraction
  FROM owned o WHERE o.last_value IS NOT NULL AND o.increment_by > 0 AND NOT o.cycle
)
SELECT 'PG-SCHEMA-002'::text AS check_id,
       'relation'::text AS scope,
       format('%I.%I.%I', current_database(), s.schemaname, s.sequencename)::text AS object,
       format('Sequence %s.%s is at %s of an effective maximum of %s (%s%%, threshold %s%%). %s When it runs out, every INSERT that calls nextval fails: "nextval: reached maximum value of sequence" or, if the column type is the binding limit, "integer out of range". Widening the column to bigint rewrites the whole table and every index on it, which is why this is worth seeing at 70%% rather than at 99%%.',
              s.schemaname, s.sequencename,
              to_char(s.last_value, 'FM999,999,999,999,999,999'),
              to_char(s.effective_max, 'FM999,999,999,999,999,999'),
              round(100 * s.used_fraction, 1)::text,
              round(100 * :'pg_schema_002_exhaustion_fraction'::numeric)::text,
              CASE WHEN s.owner_table IS NULL
                   THEN 'It is not owned by any column, so the limit is the sequence''s own max_value.'
                   ELSE format('It backs %s.%s.%s of type %s, whose maximum (%s) %s the sequence''s own max_value (%s).',
                               s.owner_schema, s.owner_table, s.owner_column, s.owner_type,
                               to_char(s.type_max, 'FM999,999,999,999,999,999'),
                               CASE WHEN s.type_max < s.max_value THEN 'is lower than' ELSE 'is not lower than' END,
                               to_char(s.max_value, 'FM999,999,999,999,999,999')) END) AS details,
       json_build_object('schema', s.schemaname, 'sequence', s.sequencename,
                         'last_value', s.last_value, 'max_value', s.max_value,
                         'effective_max', s.effective_max,
                         'used_fraction', round(s.used_fraction, 5),
                         'threshold_fraction', :'pg_schema_002_exhaustion_fraction'::numeric,
                         'increment_by', s.increment_by,
                         'owner_schema', s.owner_schema, 'owner_table', s.owner_table,
                         'owner_column', s.owner_column, 'owner_type', s.owner_type)::text AS evidence_json,
       'high'::text AS confidence
FROM scored s
WHERE s.used_fraction >= :'pg_schema_002_exhaustion_fraction'::numeric
  AND s.used_fraction < :'pg_schema_002_exhaustion_fraction_high'::numeric
ORDER BY s.used_fraction DESC;
\echo '@@END PG-SCHEMA-002'
\else
\echo '@@SKIP PG-SCHEMA-002 needs PostgreSQL 10 or newer'
\endif

-- ======== PG-SEC-015  P50  User tables granting write privileges to PUBLIC ========
\echo '@@CHECK PG-SEC-015'
-- check: PG-SEC-015
-- title: User tables granting write privileges to PUBLIC
-- priority: 50
-- scope: relation
-- cost: 1
SELECT 'PG-SEC-015'::text AS check_id,
       'relation'::text  AS scope,
       format('%I.%I.%I', current_database(), n.nspname, c.relname)::text AS object,
       format('%s %s.%s grants %s to PUBLIC. Every role that can connect to database %s holds those privileges on it, including roles created later and roles that were only meant to read something else. Size %s, %s estimated rows. Full ACL: %s. Fix with REVOKE %s ON %s.%s FROM PUBLIC, after checking which roles were relying on the PUBLIC grant.',
              CASE c.relkind WHEN 'r' THEN 'Table' WHEN 'p' THEN 'Partitioned table'
                             WHEN 'm' THEN 'Materialized view' WHEN 'v' THEN 'View'
                             WHEN 'f' THEN 'Foreign table' WHEN 'S' THEN 'Sequence' ELSE 'Relation' END,
              n.nspname, c.relname, g.privs, current_database(),
              pg_size_pretty(pg_total_relation_size(c.oid)),
              to_char(greatest(c.reltuples, 0)::bigint, 'FM999,999,999,999'),
              array_to_string(c.relacl, ', '),
              g.privs, quote_ident(n.nspname), quote_ident(c.relname)) AS details,
       json_build_object('schema', n.nspname, 'relname', c.relname, 'relkind', c.relkind,
                         'public_privileges', g.privs,
                         'relacl', array_to_string(c.relacl, ';'),
                         'owner', pg_get_userbyid(c.relowner),
                         'total_bytes', pg_total_relation_size(c.oid),
                         'reltuples', greatest(c.reltuples, 0)::bigint)::text AS evidence_json,
       'high'::text AS confidence
FROM pg_class c
JOIN pg_namespace n ON n.oid = c.relnamespace
CROSS JOIN LATERAL (
  SELECT string_agg(DISTINCT a.privilege_type, ', ' ORDER BY a.privilege_type) AS privs
  FROM aclexplode(c.relacl) a
  WHERE a.grantee = 0 AND a.privilege_type IN ('INSERT', 'UPDATE', 'DELETE', 'TRUNCATE')
) g
WHERE c.relkind IN ('r', 'p', 'm', 'v', 'f', 'S')
  AND n.nspname NOT IN ('pg_catalog', 'information_schema', 'pg_toast')
  AND g.privs IS NOT NULL
ORDER BY pg_total_relation_size(c.oid) DESC;
\echo '@@END PG-SEC-015'

-- ======== PG-VAC-001  P50  Autovacuum running more than 6 hours on one relation ========
SELECT (current_setting('server_version_num')::int >= 90600) AS gate_pg_vac_001 \gset
\if :gate_pg_vac_001
\echo '@@CHECK PG-VAC-001'
-- check: PG-VAC-001
-- title: Autovacuum running more than 6 hours on one relation
-- priority: 50
-- scope: relation
-- cost: 0
-- min_version: 9.6
-- thresholds: duration_seconds
WITH cfg AS (
  SELECT (SELECT setting::numeric FROM pg_settings WHERE name = 'autovacuum_vacuum_cost_delay') AS delay_ms,
         CASE WHEN (SELECT setting::int FROM pg_settings WHERE name = 'autovacuum_vacuum_cost_limit') < 0
              THEN (SELECT setting::numeric FROM pg_settings WHERE name = 'vacuum_cost_limit')
              ELSE (SELECT setting::numeric FROM pg_settings WHERE name = 'autovacuum_vacuum_cost_limit') END AS eff_limit,
         (SELECT setting::numeric FROM pg_settings WHERE name = 'vacuum_cost_page_dirty') AS dirty_cost,
         current_setting('block_size')::numeric AS bs
)
SELECT 'PG-VAC-001'::text AS check_id,
       'relation'::text   AS scope,
       format('%I.%I.%I', current_database(), n.nspname, c.relname)::text AS object,
       format('Vacuum has been running for %s (threshold %s). Phase "%s", %s of %s heap blocks scanned (%s%%), %s index vacuum cycles so far. Backend pid %s, %s. With autovacuum_vacuum_cost_delay = %s and cost limit %s the worker moves roughly %s MB/s of dirty pages, so this relation needs its own cost settings or partitioning.',
              justify_interval(date_trunc('second', now() - a.xact_start)),
              (:'pg_vac_001_duration_seconds'::int || ' seconds')::interval,
              p.phase,
              to_char(p.heap_blks_scanned, 'FM999,999,999,999'),
              to_char(p.heap_blks_total, 'FM999,999,999,999'),
              round(100.0 * p.heap_blks_scanned / nullif(p.heap_blks_total, 0), 1)::text,
              p.index_vacuum_count, p.pid,
              coalesce(a.backend_type, 'unknown backend'),
              cfg.delay_ms::text || ' ms',
              cfg.eff_limit::text,
              round((cfg.eff_limit / cfg.dirty_cost) * (1000.0 / greatest(cfg.delay_ms, 0.1)) * cfg.bs / 1048576.0, 1)::text) AS details,
       json_build_object(
              'pid', p.pid, 'phase', p.phase,
              'duration_seconds', round(extract(epoch FROM now() - a.xact_start))::bigint,
              'threshold_seconds', :'pg_vac_001_duration_seconds'::int,
              'heap_blks_total', p.heap_blks_total, 'heap_blks_scanned', p.heap_blks_scanned,
              'index_vacuum_count', p.index_vacuum_count,
              'total_bytes', pg_total_relation_size(c.oid),
              'backend_type', a.backend_type,
              'autovacuum_vacuum_cost_delay_ms', cfg.delay_ms,
              'effective_cost_limit', cfg.eff_limit,
              'vacuum_cost_page_dirty', cfg.dirty_cost,
              'dirty_mb_per_sec', round((cfg.eff_limit / cfg.dirty_cost) * (1000.0 / greatest(cfg.delay_ms, 0.1)) * cfg.bs / 1048576.0, 2))::text AS evidence_json,
       'high'::text AS confidence
FROM pg_stat_progress_vacuum p
JOIN pg_class c     ON c.oid = p.relid
JOIN pg_namespace n ON n.oid = c.relnamespace
JOIN pg_stat_activity a ON a.pid = p.pid
CROSS JOIN cfg
WHERE a.xact_start IS NOT NULL
  AND now() - a.xact_start >= (:'pg_vac_001_duration_seconds'::int || ' seconds')::interval
ORDER BY a.xact_start;
\echo '@@END PG-VAC-001'
\else
\echo '@@SKIP PG-VAC-001 needs PostgreSQL 9.6 or newer'
\endif

-- ======== PG-VAC-003  P50  Tables overdue for vacuum ========
\echo '@@CHECK PG-VAC-003'
-- check: PG-VAC-003
-- title: Tables overdue for vacuum
-- priority: 50
-- scope: relation
-- cost: 1
-- thresholds: dead_multiple, min_dead_tuples, min_bytes, top_n
WITH eff AS (
  SELECT t.relid, t.schemaname, t.relname, t.n_dead_tup, t.n_live_tup,
         t.last_vacuum, t.last_autovacuum, t.n_mod_since_analyze,
         pg_relation_size(t.relid) AS rel_bytes,
         coalesce(substring(array_to_string(c.reloptions, ' ') from 'autovacuum_vacuum_threshold=([0-9.]+)')::numeric,
                  current_setting('autovacuum_vacuum_threshold')::numeric) AS thr,
         coalesce(substring(array_to_string(c.reloptions, ' ') from 'autovacuum_vacuum_scale_factor=([0-9.]+)')::numeric,
                  current_setting('autovacuum_vacuum_scale_factor')::numeric) AS scale
  FROM pg_stat_user_tables t
  JOIN pg_class c ON c.oid = t.relid
)
SELECT 'PG-VAC-003'::text AS check_id,
       'relation'::text   AS scope,
       format('%I.%I.%I', current_database(), e.schemaname, e.relname)::text AS object,
       format('%s dead tuples against %s live (%s%% dead), %s of the effective autovacuum threshold of %s rows (threshold + scale_factor x live = %s + %s x %s). Relation size %s. Last vacuum %s, last autovacuum %s.',
              to_char(e.n_dead_tup, 'FM999,999,999,999'),
              to_char(e.n_live_tup, 'FM999,999,999,999'),
              round(100.0 * e.n_dead_tup / nullif(e.n_dead_tup + e.n_live_tup, 0), 1)::text,
              round(e.n_dead_tup / nullif(e.thr + e.scale * greatest(e.n_live_tup, 0), 0), 1)::text || 'x',
              to_char(round(e.thr + e.scale * greatest(e.n_live_tup, 0)), 'FM999,999,999,999'),
              e.thr::text, e.scale::text, to_char(e.n_live_tup, 'FM999,999,999,999'),
              pg_size_pretty(e.rel_bytes),
              coalesce(e.last_vacuum::text, 'never'),
              coalesce(e.last_autovacuum::text, 'never')) AS details,
       json_build_object('n_dead_tup', e.n_dead_tup, 'n_live_tup', e.n_live_tup,
                         'effective_threshold', round(e.thr + e.scale * greatest(e.n_live_tup, 0)),
                         'threshold_multiple', :'pg_vac_003_dead_multiple'::numeric,
                         'autovacuum_vacuum_threshold', e.thr,
                         'autovacuum_vacuum_scale_factor', e.scale,
                         'relation_bytes', e.rel_bytes,
                         'last_vacuum', e.last_vacuum, 'last_autovacuum', e.last_autovacuum)::text AS evidence_json,
       'medium'::text AS confidence
FROM eff e
WHERE e.n_dead_tup >= :'pg_vac_003_min_dead_tuples'::bigint
  AND e.rel_bytes  >= :'pg_vac_003_min_bytes'::bigint
  AND e.n_dead_tup >  :'pg_vac_003_dead_multiple'::numeric * (e.thr + e.scale * greatest(e.n_live_tup, 0))
ORDER BY e.n_dead_tup DESC
LIMIT :'pg_vac_003_top_n'::int;
\echo '@@END PG-VAC-003'

-- ======== PG-VAC-004  P50  Large tables never analyzed or with stale statistics ========
\echo '@@CHECK PG-VAC-004'
-- check: PG-VAC-004
-- title: Large tables never analyzed or with stale statistics
-- priority: 50
-- scope: relation
-- cost: 1
-- thresholds: never_analyzed_rows, stale_fraction, stale_min_rows, top_n
SELECT 'PG-VAC-004'::text AS check_id,
       'relation'::text   AS scope,
       format('%I.%I.%I', current_database(), t.schemaname, t.relname)::text AS object,
       CASE WHEN t.last_analyze IS NULL AND t.last_autoanalyze IS NULL
            THEN format('Never analyzed. %s live rows, %s modified since the last analyze, relation size %s. The planner has only the default estimates for this table, so row-count guesses can be wrong by orders of magnitude.',
                        to_char(t.n_live_tup, 'FM999,999,999,999'),
                        to_char(t.n_mod_since_analyze, 'FM999,999,999,999'),
                        pg_size_pretty(pg_relation_size(t.relid)))
            ELSE format('%s rows modified since the last analyze against %s live rows (%s%%, threshold %s%%). Last analyze %s, last autoanalyze %s. Relation size %s.',
                        to_char(t.n_mod_since_analyze, 'FM999,999,999,999'),
                        to_char(t.n_live_tup, 'FM999,999,999,999'),
                        round(100.0 * t.n_mod_since_analyze / nullif(t.n_live_tup, 0), 1)::text,
                        round(100 * :'pg_vac_004_stale_fraction'::numeric)::text,
                        coalesce(t.last_analyze::text, 'never'),
                        coalesce(t.last_autoanalyze::text, 'never'),
                        pg_size_pretty(pg_relation_size(t.relid)))
       END AS details,
       json_build_object('n_live_tup', t.n_live_tup, 'n_mod_since_analyze', t.n_mod_since_analyze,
                         'last_analyze', t.last_analyze, 'last_autoanalyze', t.last_autoanalyze,
                         'relation_bytes', pg_relation_size(t.relid),
                         'never_analyzed', (t.last_analyze IS NULL AND t.last_autoanalyze IS NULL),
                         'stale_fraction_threshold', :'pg_vac_004_stale_fraction'::numeric)::text AS evidence_json,
       'medium'::text AS confidence
FROM pg_stat_user_tables t
WHERE (t.last_analyze IS NULL AND t.last_autoanalyze IS NULL
       AND t.n_live_tup >= :'pg_vac_004_never_analyzed_rows'::bigint)
   OR (t.n_mod_since_analyze > :'pg_vac_004_stale_fraction'::numeric * greatest(t.n_live_tup, 0)
       AND t.n_live_tup >= :'pg_vac_004_stale_min_rows'::bigint)
ORDER BY t.n_live_tup DESC
LIMIT :'pg_vac_004_top_n'::int;
\echo '@@END PG-VAC-004'

-- ======== PG-VAC-006  P50  Estimated table bloat over 50 percent (1 GB or more wasted) ========
\echo '@@CHECK PG-VAC-006'
-- check: PG-VAC-006
-- title: Estimated table bloat over 50 percent (1 GB or more wasted)
-- priority: 50
-- scope: relation
-- cost: 1
-- thresholds: bloat_pct, wasted_bytes, min_bytes, top_n
-- estimator: lib/bloat_table.sql (re-derived from documented page layout; no third-party code)
WITH const AS (
  SELECT current_setting('block_size')::numeric AS bs,
         23::numeric AS tuple_hdr, 8::numeric AS ma,
         24::numeric AS page_hdr,  4::numeric AS item_id
),
colstats AS (
  SELECT s.schemaname, s.tablename,
         sum((1 - s.null_frac)::numeric * s.avg_width)    AS datawidth,
         count(*) FILTER (WHERE s.null_frac > 0) AS nullable_cols,
         count(*)                                AS ncols
  FROM pg_stats s
  WHERE s.schemaname NOT IN ('pg_catalog', 'information_schema')
  GROUP BY 1, 2
),
tbl AS (
  SELECT c.oid, n.nspname, c.relname, c.reltuples::numeric AS reltuples,
         c.relpages::numeric AS relpages, pg_relation_size(c.oid) AS rel_bytes,
         coalesce(substring(array_to_string(c.reloptions, ' ') FROM 'fillfactor=([0-9]+)')::numeric, 100) AS fillfactor
  FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE c.relkind IN ('r', 'm')
    AND n.nspname NOT IN ('pg_catalog', 'information_schema', 'pg_toast')
),
est AS (
  SELECT t.oid, t.nspname, t.relname, t.reltuples, t.relpages, t.rel_bytes, t.fillfactor,
         const.bs,
         ceil((const.tuple_hdr + CASE WHEN k.nullable_cols > 0 THEN ceil(k.ncols / 8.0) ELSE 0 END) / const.ma) * const.ma
           + ceil(coalesce(k.datawidth, 0) / const.ma) * const.ma AS tuple_bytes,
         greatest(1, floor(((const.bs - const.page_hdr) * t.fillfactor / 100.0)
                  / (ceil((const.tuple_hdr + CASE WHEN k.nullable_cols > 0 THEN ceil(k.ncols / 8.0) ELSE 0 END) / const.ma) * const.ma
                     + ceil(coalesce(k.datawidth, 0) / const.ma) * const.ma + const.item_id))) AS rows_per_page,
         (k.datawidth IS NULL OR t.reltuples < 0 OR t.relpages <= 0) AS is_na
  FROM tbl t
  LEFT JOIN colstats k ON k.schemaname = t.nspname AND k.tablename = t.relname
  CROSS JOIN const
),
scored AS (
  SELECT nspname, relname, reltuples, relpages, rel_bytes, fillfactor, tuple_bytes, rows_per_page,
         ceil(reltuples / rows_per_page)                            AS expected_pages,
         greatest(relpages - ceil(reltuples / rows_per_page), 0)    AS bloat_pages,
         (greatest(relpages - ceil(reltuples / rows_per_page), 0) * bs)::bigint AS bloat_bytes,
         round(100.0 * greatest(relpages - ceil(reltuples / rows_per_page), 0) / nullif(relpages, 0), 1) AS bloat_pct
  FROM est WHERE NOT is_na
)
SELECT 'PG-VAC-006'::text AS check_id,
       'relation'::text  AS scope,
       format('%I.%I.%I', current_database(), s.nspname, s.relname)::text AS object,
       format('Estimated %s%% bloat (threshold %s%%): %s of %s is space not occupied by live rows, against %s estimated live rows at %s bytes each and fillfactor %s. Estimated from pg_stats and pg_class only; confirm with pgstattuple_approx() before scheduling a rewrite.',
              s.bloat_pct::text, :'pg_vac_006_bloat_pct'::text,
              pg_size_pretty(s.bloat_bytes), pg_size_pretty(s.rel_bytes),
              to_char(s.reltuples::bigint, 'FM999,999,999,999'), s.tuple_bytes::text, s.fillfactor::text) AS details,
       json_build_object('bloat_pct', s.bloat_pct, 'bloat_bytes', s.bloat_bytes,
                         'relation_bytes', s.rel_bytes, 'relpages', s.relpages::bigint,
                         'expected_pages', s.expected_pages::bigint, 'reltuples', s.reltuples::bigint,
                         'estimated_tuple_bytes', s.tuple_bytes, 'fillfactor', s.fillfactor,
                         'threshold_pct', :'pg_vac_006_bloat_pct'::numeric,
                         'threshold_wasted_bytes', :'pg_vac_006_wasted_bytes'::bigint,
                         'estimator', 'lib/bloat_table.sql')::text AS evidence_json,
       'medium'::text AS confidence
FROM scored s
WHERE s.bloat_pct   >= :'pg_vac_006_bloat_pct'::numeric
  AND s.bloat_bytes >= :'pg_vac_006_wasted_bytes'::bigint
  AND s.rel_bytes  >= :'pg_vac_006_min_bytes'::bigint
ORDER BY s.bloat_bytes DESC
LIMIT :'pg_vac_006_top_n'::int;
\echo '@@END PG-VAC-006'

-- ======== PG-WRAP-004  P50  Tables driving transaction ID age ========
SELECT (current_setting('server_version_num')::int >= 90600) AS gate_pg_wrap_004 \gset
\if :gate_pg_wrap_004
\echo '@@CHECK PG-WRAP-004'
-- check: PG-WRAP-004
-- title: Tables driving transaction ID age
-- priority: 50
-- scope: relation
-- cost: 1
-- min_version: 9.6
-- thresholds: top_n, min_age
-- Emitted only when the relation ages in this database are themselves notable;
-- the report presents it under whichever of PG-WRAP-001/002/003 fired.
SELECT 'PG-WRAP-004'::text AS check_id,
       'relation'::text    AS scope,
       format('%I.%I.%I', current_database(), n.nspname, c.relname)::text AS object,
       format('%s %s: age(relfrozenxid) = %s, mxid_age(relminmxid) = %s, size %s. %s',
              CASE c.relkind WHEN 'r' THEN 'table' WHEN 'm' THEN 'materialized view'
                             WHEN 't' THEN 'toast table' WHEN 'p' THEN 'partitioned table'
                             ELSE c.relkind::text END,
              c.relname,
              to_char(age(c.relfrozenxid), 'FM999,999,999,999'),
              to_char(mxid_age(c.relminmxid), 'FM999,999,999,999'),
              pg_size_pretty(pg_total_relation_size(c.oid)),
              coalesce('an autovacuum is processing it now, phase "' || p.phase || '", ' ||
                       round(100.0 * p.heap_blks_scanned / nullif(p.heap_blks_total, 0), 1)::text || '% of heap scanned',
                       'no vacuum is currently running on it')) AS details,
       json_build_object(
              'relkind', c.relkind,
              'relfrozenxid_age', age(c.relfrozenxid),
              'relminmxid_age', mxid_age(c.relminmxid),
              'total_bytes', pg_total_relation_size(c.oid),
              'vacuum_phase', p.phase,
              'heap_blks_total', p.heap_blks_total,
              'heap_blks_scanned', p.heap_blks_scanned,
              'reloptions', array_to_string(c.reloptions, ';'))::text AS evidence_json,
       'high'::text AS confidence
FROM pg_class c
JOIN pg_namespace n ON n.oid = c.relnamespace
LEFT JOIN pg_stat_progress_vacuum p ON p.relid = c.oid
WHERE c.relkind IN ('r', 'm', 't', 'p')
  AND c.relfrozenxid <> '0'::xid
  AND greatest(age(c.relfrozenxid), mxid_age(c.relminmxid)) >= :'pg_wrap_004_min_age'::bigint
ORDER BY greatest(age(c.relfrozenxid), mxid_age(c.relminmxid)) DESC
LIMIT :'pg_wrap_004_top_n'::int;
\echo '@@END PG-WRAP-004'
\else
\echo '@@SKIP PG-WRAP-004 needs PostgreSQL 9.6 or newer'
\endif

-- ======== PG-DUR-005  P100  Unlogged tables present ========
\echo '@@CHECK PG-DUR-005'
-- check: PG-DUR-005
-- title: Unlogged tables present
-- priority: 100
-- scope: relation
-- cost: 1
SELECT 'PG-DUR-005'::text AS check_id,
       'relation'::text   AS scope,
       format('%I.%I.%I', current_database(), n.nspname, c.relname)::text AS object,
       format('Unlogged %s, %s, %s estimated rows. Its contents are not written to WAL: they are truncated to empty on crash recovery, are not present on any standby, and are not in any base backup or PITR restore. That is the right trade for a scratch or staging relation and a data-loss surprise for anything else.',
              CASE c.relkind WHEN 'r' THEN 'table' WHEN 'p' THEN 'partitioned table'
                             WHEN 'm' THEN 'materialized view' ELSE c.relkind::text END,
              pg_size_pretty(pg_total_relation_size(c.oid)),
              to_char(greatest(c.reltuples, 0)::bigint, 'FM999,999,999,999')) AS details,
       json_build_object('relkind', c.relkind, 'total_bytes', pg_total_relation_size(c.oid),
                         'reltuples', greatest(c.reltuples, 0)::bigint,
                         'schema', n.nspname, 'relname', c.relname)::text AS evidence_json,
       'high'::text AS confidence
FROM pg_class c
JOIN pg_namespace n ON n.oid = c.relnamespace
WHERE c.relpersistence = 'u'
  AND n.nspname NOT LIKE 'pg_temp%'
  AND n.nspname NOT LIKE 'pg_toast%'
ORDER BY pg_total_relation_size(c.oid) DESC;
\echo '@@END PG-DUR-005'

-- ======== PG-IDX-005  P100  Overlapping indexes (leading-column prefix) ========
\echo '@@CHECK PG-IDX-005'
-- check: PG-IDX-005
-- title: Overlapping indexes (leading-column prefix)
-- priority: 100
-- scope: index
-- cost: 1
WITH idx AS (
  SELECT i.indexrelid, i.indrelid, n.nspname, tc.relname AS table_name, ic.relname AS index_name,
         ic.relam, i.indnkeyatts, i.indisunique,
         (string_to_array(i.indkey::text, ' '))[1:i.indnkeyatts]   AS keys,
         (string_to_array(i.indclass::text, ' '))[1:i.indnkeyatts] AS classes,
         (string_to_array(i.indoption::text, ' '))[1:i.indnkeyatts] AS options,
         coalesce(pg_get_expr(i.indpred, i.indrelid), '')          AS pred,
         pg_relation_size(i.indexrelid)                            AS index_bytes,
         s.idx_scan
  FROM pg_index i
  JOIN pg_class ic    ON ic.oid = i.indexrelid
  JOIN pg_class tc    ON tc.oid = i.indrelid
  JOIN pg_namespace n ON n.oid = ic.relnamespace
  LEFT JOIN pg_stat_user_indexes s ON s.indexrelid = i.indexrelid
  WHERE i.indisvalid AND i.indexprs IS NULL
    AND n.nspname NOT IN ('pg_catalog', 'information_schema', 'pg_toast')
)
SELECT 'PG-IDX-005'::text AS check_id,
       'index'::text      AS scope,
       format('%I.%I.%I', current_database(), a.nspname, a.index_name)::text AS object,
       format('Index %s on %s.%s is a strict leading-column prefix of %s: %s against %s. Anything the shorter index can answer, the longer one can answer too, so the shorter one is usually redundant write cost (%s, %s scans recorded; the wider index has %s and %s scans). It is P100 rather than P50 because prefixes are sometimes deliberate: a narrower index is cheaper to maintain and fits more entries per page, and INCLUDE columns or a different sort direction can make the wider one unusable for a given query. Check the plans before dropping.',
              a.index_name, a.nspname, a.table_name, b.index_name,
              pg_get_indexdef(a.indexrelid), pg_get_indexdef(b.indexrelid),
              pg_size_pretty(a.index_bytes), coalesce(a.idx_scan::text, 'unknown'),
              pg_size_pretty(b.index_bytes), coalesce(b.idx_scan::text, 'unknown')) AS details,
       json_build_object('schema', a.nspname, 'table', a.table_name,
                         'narrow_index', a.index_name, 'wide_index', b.index_name,
                         'narrow_bytes', a.index_bytes, 'wide_bytes', b.index_bytes,
                         'narrow_idx_scan', a.idx_scan, 'wide_idx_scan', b.idx_scan,
                         'narrow_def', pg_get_indexdef(a.indexrelid),
                         'wide_def', pg_get_indexdef(b.indexrelid))::text AS evidence_json,
       'medium'::text AS confidence
FROM idx a
JOIN idx b
  ON b.indrelid = a.indrelid
 AND b.indexrelid <> a.indexrelid
 AND b.relam = a.relam
 AND b.pred = a.pred
 AND b.indnkeyatts > a.indnkeyatts
 AND b.keys[1:a.indnkeyatts]    = a.keys
 AND b.classes[1:a.indnkeyatts] = a.classes
 AND b.options[1:a.indnkeyatts] = a.options
WHERE NOT a.indisunique
ORDER BY a.index_bytes DESC;
\echo '@@END PG-IDX-005'

-- ======== PG-IDX-012  P100  Write-heavy table with many indexes ========
\echo '@@CHECK PG-IDX-012'
-- check: PG-IDX-012
-- title: Write-heavy table with many indexes
-- priority: 100
-- scope: relation
-- cost: 1
-- thresholds: min_indexes, min_writes
SELECT 'PG-IDX-012'::text AS check_id,
       'relation'::text   AS scope,
       format('%I.%I.%I', current_database(), t.schemaname, t.relname)::text AS object,
       format('Table %s.%s carries %s indexes (threshold %s) and has taken %s writes since the statistics reset (threshold %s): %s inserts, %s updates, %s deletes. Every insert, and every update that cannot be heap-only, writes an entry into all %s indexes; heap-only updates are %s%% of updates here (PG-VAC-012 measures that). Heap %s, indexes %s. %s of these indexes have never been scanned (PG-IDX-002/003 lists them).',
              t.schemaname, t.relname, c.idx_count, :'pg_idx_012_min_indexes'::text,
              to_char(t.n_tup_ins + t.n_tup_upd + t.n_tup_del, 'FM999,999,999,999'),
              to_char(:'pg_idx_012_min_writes'::bigint, 'FM999,999,999,999'),
              to_char(t.n_tup_ins, 'FM999,999,999,999'),
              to_char(t.n_tup_upd, 'FM999,999,999,999'),
              to_char(t.n_tup_del, 'FM999,999,999,999'),
              c.idx_count,
              round(100.0 * t.n_tup_hot_upd / nullif(t.n_tup_upd, 0), 1)::text,
              pg_size_pretty(pg_table_size(t.relid)),
              pg_size_pretty(pg_indexes_size(t.relid)),
              c.unused_count) AS details,
       json_build_object('schema', t.schemaname, 'table', t.relname,
                         'index_count', c.idx_count, 'unused_index_count', c.unused_count,
                         'writes', t.n_tup_ins + t.n_tup_upd + t.n_tup_del,
                         'n_tup_ins', t.n_tup_ins, 'n_tup_upd', t.n_tup_upd, 'n_tup_del', t.n_tup_del,
                         'n_tup_hot_upd', t.n_tup_hot_upd,
                         'table_bytes', pg_table_size(t.relid),
                         'indexes_bytes', pg_indexes_size(t.relid),
                         'threshold_indexes', :'pg_idx_012_min_indexes'::int,
                         'threshold_writes', :'pg_idx_012_min_writes'::bigint)::text AS evidence_json,
       'high'::text AS confidence
FROM pg_stat_user_tables t
CROSS JOIN LATERAL (
  SELECT count(*) AS idx_count,
         count(*) FILTER (WHERE coalesce(si.idx_scan, 0) = 0) AS unused_count
  FROM pg_index i
  LEFT JOIN pg_stat_user_indexes si ON si.indexrelid = i.indexrelid
  WHERE i.indrelid = t.relid AND i.indisvalid
) c
WHERE c.idx_count >= :'pg_idx_012_min_indexes'::int
  AND t.n_tup_ins + t.n_tup_upd + t.n_tup_del >= :'pg_idx_012_min_writes'::bigint
ORDER BY t.n_tup_ins + t.n_tup_upd + t.n_tup_del DESC;
\echo '@@END PG-IDX-012'

-- ======== PG-QRY-008  P100  One statement dominates execution time ========
\echo '@@CHECK PG-QRY-008'
-- check: PG-QRY-008
-- title: One statement dominates execution time
-- priority: 100
-- scope: query
-- cost: 1
-- thresholds: dominance, min_calls
\set ON_ERROR_STOP off
SELECT (to_regclass('pg_stat_statements') IS NOT NULL) AS pg_qry_008_pgss \gset
\if :pg_qry_008_pgss
SELECT EXISTS (SELECT 1 FROM pg_attribute
               WHERE attrelid = to_regclass('pg_stat_statements')
                 AND attname = 'total_exec_time' AND NOT attisdropped) AS pg_qry_008_v18 \gset
WITH q AS (
\if :pg_qry_008_v18
  SELECT queryid, query, calls, rows,
         total_exec_time::numeric AS total_ms, mean_exec_time::numeric AS mean_ms,
         stddev_exec_time::numeric AS stddev_ms,
         shared_blks_read, shared_blks_hit, temp_blks_read, temp_blks_written, userid
  FROM pg_stat_statements WHERE dbid = (SELECT oid FROM pg_database WHERE datname = current_database())
\else
  SELECT queryid, query, calls, rows,
         total_time::numeric AS total_ms, mean_time::numeric AS mean_ms,
         stddev_time::numeric AS stddev_ms,
         shared_blks_read, shared_blks_hit, temp_blks_read, temp_blks_written, userid
  FROM pg_stat_statements WHERE dbid = (SELECT oid FROM pg_database WHERE datname = current_database())
\endif
),
tot AS (SELECT sum(total_ms) AS all_ms, sum(calls) AS all_calls FROM q)

SELECT 'PG-QRY-008'::text AS check_id,
       'query'::text      AS scope,
       ('queryid:' || q.queryid::text)::text AS object,
       format('One statement accounts for %s%% of all execution time recorded for database %s (threshold %s%%): %s ms across %s calls, mean %s ms, %s rows per call. Total recorded across all statements: %s ms over %s calls. Whatever else is on the tuning list, this is the statement where an improvement is worth the most: halving it removes %s%% of the server''s recorded query time. Run by role %s. Statement: %s',
              round(100.0 * q.total_ms / nullif(t.all_ms, 0), 1)::text, current_database(),
              round(100 * :'pg_qry_008_dominance'::numeric)::text,
              to_char(round(q.total_ms), 'FM999,999,999,999'),
              to_char(q.calls, 'FM999,999,999,999'),
              round(q.mean_ms, 2)::text,
              round(q.rows::numeric / nullif(q.calls, 0), 1)::text,
              to_char(round(t.all_ms), 'FM999,999,999,999'),
              to_char(t.all_calls, 'FM999,999,999,999'),
              round(50.0 * q.total_ms / nullif(t.all_ms, 0), 1)::text,
              coalesce((SELECT rolname FROM pg_roles WHERE oid = q.userid), 'unknown'),
              left(regexp_replace(q.query, '\s+', ' ', 'g'), 300)) AS details,
       json_build_object('queryid', q.queryid, 'calls', q.calls,
                         'total_ms', round(q.total_ms, 2), 'mean_ms', round(q.mean_ms, 3),
                         'pct_of_total_time', round(100.0 * q.total_ms / nullif(t.all_ms, 0), 2),
                         'threshold_fraction', :'pg_qry_008_dominance'::numeric,
                         'all_statements_ms', round(t.all_ms, 2), 'all_calls', t.all_calls,
                         'rows_per_call', round(q.rows::numeric / nullif(q.calls, 0), 2),
                         'query', left(regexp_replace(q.query, '\s+', ' ', 'g'), 300))::text AS evidence_json,
       'medium'::text AS confidence
FROM q CROSS JOIN tot t
WHERE q.calls >= :'pg_qry_008_min_calls'::bigint
  AND q.total_ms >= :'pg_qry_008_dominance'::numeric * t.all_ms
ORDER BY q.total_ms DESC;
\endif
\echo '@@END PG-QRY-008'

-- ======== PG-QRY-009  P100  Statements spilling to temp files ========
\echo '@@CHECK PG-QRY-009'
-- check: PG-QRY-009
-- title: Statements spilling to temp files
-- priority: 100
-- scope: query
-- cost: 1
-- thresholds: temp_bytes, top_n
\set ON_ERROR_STOP off
SELECT (to_regclass('pg_stat_statements') IS NOT NULL) AS pg_qry_009_pgss \gset
\if :pg_qry_009_pgss
SELECT EXISTS (SELECT 1 FROM pg_attribute
               WHERE attrelid = to_regclass('pg_stat_statements')
                 AND attname = 'total_exec_time' AND NOT attisdropped) AS pg_qry_009_v18 \gset
WITH q AS (
\if :pg_qry_009_v18
  SELECT queryid, query, calls, rows,
         total_exec_time::numeric AS total_ms, mean_exec_time::numeric AS mean_ms,
         stddev_exec_time::numeric AS stddev_ms,
         shared_blks_read, shared_blks_hit, temp_blks_read, temp_blks_written, userid
  FROM pg_stat_statements WHERE dbid = (SELECT oid FROM pg_database WHERE datname = current_database())
\else
  SELECT queryid, query, calls, rows,
         total_time::numeric AS total_ms, mean_time::numeric AS mean_ms,
         stddev_time::numeric AS stddev_ms,
         shared_blks_read, shared_blks_hit, temp_blks_read, temp_blks_written, userid
  FROM pg_stat_statements WHERE dbid = (SELECT oid FROM pg_database WHERE datname = current_database())
\endif
),
tot AS (SELECT sum(total_ms) AS all_ms, sum(calls) AS all_calls FROM q)

SELECT 'PG-QRY-009'::text AS check_id,
       'query'::text      AS scope,
       ('queryid:' || q.queryid::text)::text AS object,
       format('This statement has written %s of temporary files since the statistics reset (threshold %s) across %s calls: about %s per call. That is a sort, hash or materialise step that did not fit in work_mem (currently %s) and went to disk instead - each spill is a write and a re-read of data that could have stayed in memory. Mean execution time %s ms, %s rows per call. Raise work_mem for the role that runs this (%s) rather than globally, because the global value multiplies by max_connections in PG-MEM-003. Statement: %s',
              pg_size_pretty((q.temp_blks_written * current_setting('block_size')::bigint)::bigint),
              pg_size_pretty(:'pg_qry_009_temp_bytes'::bigint),
              to_char(q.calls, 'FM999,999,999,999'),
              pg_size_pretty((q.temp_blks_written * current_setting('block_size')::bigint / greatest(q.calls, 1))::bigint),
              current_setting('work_mem'),
              round(q.mean_ms, 2)::text,
              round(q.rows::numeric / nullif(q.calls, 0), 1)::text,
              coalesce((SELECT rolname FROM pg_roles WHERE oid = q.userid), 'unknown'),
              left(regexp_replace(q.query, '\s+', ' ', 'g'), 300)) AS details,
       json_build_object('queryid', q.queryid, 'calls', q.calls,
                         'temp_blks_written', q.temp_blks_written,
                         'temp_bytes', (q.temp_blks_written * current_setting('block_size')::bigint)::bigint,
                         'temp_bytes_per_call', (q.temp_blks_written * current_setting('block_size')::bigint / greatest(q.calls, 1))::bigint,
                         'threshold_bytes', :'pg_qry_009_temp_bytes'::bigint,
                         'mean_ms', round(q.mean_ms, 3),
                         'work_mem', current_setting('work_mem'),
                         'usename', (SELECT rolname FROM pg_roles WHERE oid = q.userid),
                         'query', left(regexp_replace(q.query, '\s+', ' ', 'g'), 300))::text AS evidence_json,
       'medium'::text AS confidence
FROM q CROSS JOIN tot t
WHERE q.temp_blks_written * current_setting('block_size')::bigint >= :'pg_qry_009_temp_bytes'::bigint
ORDER BY q.temp_blks_written DESC
LIMIT :'pg_qry_009_top_n'::int;
\endif
\echo '@@END PG-QRY-009'

-- ======== PG-QRY-014  P100  JIT overhead significant ========
SELECT (current_setting('server_version_num')::int >= 150000) AS gate_pg_qry_014 \gset
\if :gate_pg_qry_014
\echo '@@CHECK PG-QRY-014'
-- check: PG-QRY-014
-- title: JIT overhead significant
-- priority: 100
-- scope: query
-- cost: 1
-- min_version: 15
-- thresholds: jit_fraction
\set ON_ERROR_STOP off
SELECT (to_regclass('pg_stat_statements') IS NOT NULL) AS pg_qry_014_pgss \gset
\if :pg_qry_014_pgss
SELECT EXISTS (SELECT 1 FROM pg_attribute
               WHERE attrelid = to_regclass('pg_stat_statements')
                 AND attname = 'jit_generation_time' AND NOT attisdropped) AS pg_qry_014_has_jit \gset
\if :pg_qry_014_has_jit
WITH j AS (
  SELECT sum(jit_generation_time + jit_inlining_time + jit_optimization_time + jit_emission_time)::numeric AS jit_ms,
         sum(total_exec_time)::numeric AS total_ms,
         sum(jit_functions) AS jit_functions,
         count(*) FILTER (WHERE jit_functions > 0) AS jitted_statements
  FROM pg_stat_statements
  WHERE dbid = (SELECT oid FROM pg_database WHERE datname = current_database())
)
SELECT 'PG-QRY-014'::text AS check_id,
       'query'::text      AS scope,
       'jit'::text        AS object,
       format('JIT compilation accounts for %s ms of the %s ms of execution time recorded for this database (%s%%, threshold %s%%), across %s statements and %s compiled functions. JIT pays for itself on long analytical queries and costs pure overhead on short ones: the planner decides from an estimated cost (jit_above_cost = %s), and an over-estimate on an OLTP statement buys a compilation that outlasts the query. Settings: jit = %s, jit_above_cost = %s, jit_inline_above_cost = %s, jit_optimize_above_cost = %s. Raising the thresholds is usually better than turning JIT off.',
              to_char(round(j.jit_ms), 'FM999,999,999,999'),
              to_char(round(j.total_ms), 'FM999,999,999,999'),
              round(100.0 * j.jit_ms / nullif(j.total_ms, 0), 1)::text,
              round(100 * :'pg_qry_014_jit_fraction'::numeric)::text,
              j.jitted_statements, to_char(j.jit_functions, 'FM999,999,999,999'),
              current_setting('jit_above_cost'), current_setting('jit'),
              current_setting('jit_above_cost'), current_setting('jit_inline_above_cost'),
              current_setting('jit_optimize_above_cost')) AS details,
       json_build_object('jit_ms', round(j.jit_ms, 2), 'total_ms', round(j.total_ms, 2),
                         'jit_fraction', round(j.jit_ms / nullif(j.total_ms, 0), 4),
                         'threshold_fraction', :'pg_qry_014_jit_fraction'::numeric,
                         'jit_functions', j.jit_functions, 'jitted_statements', j.jitted_statements,
                         'jit', current_setting('jit'),
                         'jit_above_cost', current_setting('jit_above_cost'),
                         'jit_inline_above_cost', current_setting('jit_inline_above_cost'),
                         'jit_optimize_above_cost', current_setting('jit_optimize_above_cost'))::text AS evidence_json,
       'medium'::text AS confidence
FROM j
WHERE j.total_ms > 0
  AND j.jit_ms >= :'pg_qry_014_jit_fraction'::numeric * j.total_ms;
\endif
\endif
\echo '@@END PG-QRY-014'
\else
\echo '@@SKIP PG-QRY-014 needs PostgreSQL 15 or newer'
\endif

-- ======== PG-SCHEMA-005  P100  Very large table not partitioned ========
SELECT (current_setting('server_version_num')::int >= 100000) AS gate_pg_schema_005 \gset
\if :gate_pg_schema_005
\echo '@@CHECK PG-SCHEMA-005'
-- check: PG-SCHEMA-005
-- title: Very large table not partitioned
-- priority: 100
-- scope: relation
-- cost: 1
-- min_version: 10
-- thresholds: min_bytes
SELECT 'PG-SCHEMA-005'::text AS check_id,
       'relation'::text      AS scope,
       format('%I.%I.%I', current_database(), n.nspname, c.relname)::text AS object,
       format('Table %s.%s is %s total (%s heap, %s indexes, %s toast) with %s estimated rows, and is neither partitioned nor a partition. Every operation that has to touch the whole relation - a vacuum, a freeze, an index build, a REINDEX, an ALTER TABLE that rewrites - is one long single operation on this table, and deleting old rows means a DELETE plus a vacuum rather than a DROP of a partition. relfrozenxid age is %s. This is advisory: partitioning is a schema change with real cost, and it pays only when there is a natural range key and a retention policy.',
              n.nspname, c.relname,
              pg_size_pretty(pg_total_relation_size(c.oid)),
              pg_size_pretty(pg_table_size(c.oid)),
              pg_size_pretty(pg_indexes_size(c.oid)),
              pg_size_pretty(coalesce(pg_total_relation_size(c.reltoastrelid), 0)),
              to_char(greatest(c.reltuples, 0)::bigint, 'FM999,999,999,999'),
              to_char(age(c.relfrozenxid), 'FM999,999,999,999')) AS details,
       json_build_object('schema', n.nspname, 'table', c.relname,
                         'total_bytes', pg_total_relation_size(c.oid),
                         'heap_bytes', pg_table_size(c.oid),
                         'index_bytes', pg_indexes_size(c.oid),
                         'toast_bytes', coalesce(pg_total_relation_size(c.reltoastrelid), 0),
                         'reltuples', greatest(c.reltuples, 0)::bigint,
                         'relfrozenxid_age', age(c.relfrozenxid),
                         'threshold_bytes', :'pg_schema_005_min_bytes'::bigint)::text AS evidence_json,
       'medium'::text AS confidence
FROM pg_class c
JOIN pg_namespace n ON n.oid = c.relnamespace
WHERE c.relkind = 'r'
  AND n.nspname NOT IN ('pg_catalog', 'information_schema', 'pg_toast')
  AND NOT EXISTS (SELECT 1 FROM pg_inherits i WHERE i.inhrelid = c.oid)
  AND pg_total_relation_size(c.oid) >= :'pg_schema_005_min_bytes'::bigint
ORDER BY pg_total_relation_size(c.oid) DESC;
\echo '@@END PG-SCHEMA-005'
\else
\echo '@@SKIP PG-SCHEMA-005 needs PostgreSQL 10 or newer'
\endif

-- ======== PG-SCHEMA-006  P100  Rows accumulating in a DEFAULT partition ========
SELECT (current_setting('server_version_num')::int >= 110000) AS gate_pg_schema_006 \gset
\if :gate_pg_schema_006
\echo '@@CHECK PG-SCHEMA-006'
-- check: PG-SCHEMA-006
-- title: Rows accumulating in a DEFAULT partition
-- priority: 100
-- scope: relation
-- cost: 1
-- min_version: 11
-- thresholds: min_bytes, parent_fraction
WITH def AS (
  SELECT c.oid AS part_oid, n.nspname AS part_schema, c.relname AS part_name,
         pn.nspname AS parent_schema, pc.relname AS parent_name, pc.oid AS parent_oid,
         pg_total_relation_size(c.oid) AS part_bytes,
         coalesce(t.n_live_tup, greatest(c.reltuples, 0)::bigint) AS part_rows
  FROM pg_class c
  JOIN pg_namespace n  ON n.oid = c.relnamespace
  JOIN pg_inherits inh ON inh.inhrelid = c.oid
  JOIN pg_class pc     ON pc.oid = inh.inhparent
  JOIN pg_namespace pn ON pn.oid = pc.relnamespace
  LEFT JOIN pg_stat_user_tables t ON t.relid = c.oid
  WHERE c.relispartition
    AND pg_get_expr(c.relpartbound, c.oid) = 'DEFAULT'
),
scored AS (
  SELECT d.*,
         (SELECT sum(coalesce(st.n_live_tup, greatest(pc2.reltuples, 0)::bigint))
          FROM pg_inherits i2 JOIN pg_class pc2 ON pc2.oid = i2.inhrelid
          LEFT JOIN pg_stat_user_tables st ON st.relid = pc2.oid
          WHERE i2.inhparent = d.parent_oid) AS family_rows
  FROM def d
)
SELECT 'PG-SCHEMA-006'::text AS check_id,
       'relation'::text      AS scope,
       format('%I.%I.%I', current_database(), s.part_schema, s.part_name)::text AS object,
       format('The DEFAULT partition of %s.%s holds %s and %s rows, which is %s%% of the %s rows in the whole partition family (thresholds %s or %s%% of the parent). Rows land in the default partition when no other partition''s bound matches them, which almost always means the next period''s partition was never created. Two consequences: queries that should prune to one partition now also scan this one, and every future ATTACH PARTITION has to scan the entire default partition to prove no row belongs in the new one, holding an ACCESS EXCLUSIVE lock while it does.',
              s.parent_schema, s.parent_name,
              pg_size_pretty(s.part_bytes), to_char(s.part_rows, 'FM999,999,999,999'),
              round(100.0 * s.part_rows / nullif(s.family_rows, 0), 1)::text,
              to_char(s.family_rows, 'FM999,999,999,999'),
              pg_size_pretty(:'pg_schema_006_min_bytes'::bigint),
              round(100 * :'pg_schema_006_parent_fraction'::numeric)::text) AS details,
       json_build_object('parent_schema', s.parent_schema, 'parent_table', s.parent_name,
                         'default_partition', s.part_name,
                         'partition_bytes', s.part_bytes, 'partition_rows', s.part_rows,
                         'family_rows', s.family_rows,
                         'fraction_of_family', round(s.part_rows::numeric / nullif(s.family_rows, 0), 4),
                         'threshold_bytes', :'pg_schema_006_min_bytes'::bigint,
                         'threshold_fraction', :'pg_schema_006_parent_fraction'::numeric)::text AS evidence_json,
       'high'::text AS confidence
FROM scored s
WHERE s.part_bytes >= :'pg_schema_006_min_bytes'::bigint
   OR s.part_rows >= :'pg_schema_006_parent_fraction'::numeric * coalesce(s.family_rows, 0)
ORDER BY s.part_bytes DESC;
\echo '@@END PG-SCHEMA-006'
\else
\echo '@@SKIP PG-SCHEMA-006 needs PostgreSQL 11 or newer'
\endif

-- ======== PG-SEC-013  P100  PUBLIC can CREATE in schema public ========
\echo '@@CHECK PG-SEC-013'
-- check: PG-SEC-013
-- title: PUBLIC can CREATE in schema public
-- priority: 100
-- scope: schema
-- cost: 0
SELECT 'PG-SEC-013'::text AS check_id,
       'schema'::text     AS scope,
       format('%I.public', current_database())::text AS object,
       format('PUBLIC holds CREATE on schema public in database %s, so every role that can connect can create objects there. Combined with a search_path that puts public before pg_catalog - which is the default - any such role can define a function or operator that shadows a built-in one and have it executed by other users, including superusers. That is CVE-2018-1058. PostgreSQL 15 removed this grant for new databases; a database created earlier, or restored from an earlier dump, keeps it. Current ACL on schema public: %s. Roles that can log in: %s.',
              current_database(),
              coalesce(array_to_string(n.nspacl, ', '), 'default (owner only)'),
              (SELECT count(*) FROM pg_roles WHERE rolcanlogin)) AS details,
       json_build_object('schema', 'public', 'database', current_database(),
                         'nspacl', array_to_string(n.nspacl, ';'),
                         'owner', pg_get_userbyid(n.nspowner),
                         'login_roles', (SELECT count(*) FROM pg_roles WHERE rolcanlogin),
                         'server_version_num', current_setting('server_version_num')::int)::text AS evidence_json,
       'high'::text AS confidence
FROM pg_namespace n
WHERE n.nspname = 'public'
  AND EXISTS (SELECT 1 FROM aclexplode(n.nspacl) a
              WHERE a.grantee = 0 AND a.privilege_type = 'CREATE');
\echo '@@END PG-SEC-013'

-- ======== PG-SEC-014  P100  SECURITY DEFINER functions without a fixed search_path ========
\echo '@@CHECK PG-SEC-014'
-- check: PG-SEC-014
-- title: SECURITY DEFINER functions without a fixed search_path
-- priority: 100
-- scope: relation
-- cost: 1
SELECT 'PG-SEC-014'::text AS check_id,
       'relation'::text   AS scope,
       format('%I.%I.%I', current_database(), n.nspname, p.proname)::text AS object,
       format('Function %s.%s(%s) is SECURITY DEFINER, owned by %s, written in %s, with no search_path pinned in its configuration. It runs with the owner''s privileges but resolves unqualified names using the caller''s search_path, so a caller who can create objects in any schema on that path (see PG-SEC-013) can substitute their own function, operator or table and have the owner execute it. Fix: ALTER FUNCTION %s.%s(%s) SET search_path = pg_catalog, <the schemas it needs>. EXECUTE is granted to: %s.',
              n.nspname, p.proname, pg_get_function_identity_arguments(p.oid),
              pg_get_userbyid(p.proowner), l.lanname,
              quote_ident(n.nspname), quote_ident(p.proname), pg_get_function_identity_arguments(p.oid),
              coalesce((SELECT string_agg(CASE WHEN a.grantee = 0 THEN 'PUBLIC'
                                               ELSE pg_get_userbyid(a.grantee) END, ', ')
                        FROM aclexplode(p.proacl) a WHERE a.privilege_type = 'EXECUTE'),
                       'PUBLIC (default grant)')) AS details,
       json_build_object('schema', n.nspname, 'function', p.proname,
                         'arguments', pg_get_function_identity_arguments(p.oid),
                         'owner', pg_get_userbyid(p.proowner), 'language', l.lanname,
                         'proconfig', array_to_string(p.proconfig, ';'),
                         'execute_granted_to_public',
                            (p.proacl IS NULL
                             OR EXISTS (SELECT 1 FROM aclexplode(p.proacl) a
                                        WHERE a.grantee = 0 AND a.privilege_type = 'EXECUTE')))::text AS evidence_json,
       'high'::text AS confidence
FROM pg_proc p
JOIN pg_namespace n ON n.oid = p.pronamespace
JOIN pg_language  l ON l.oid = p.prolang
WHERE p.prosecdef
  AND n.nspname NOT IN ('pg_catalog', 'information_schema')
  AND coalesce(array_to_string(p.proconfig, ' '), '') !~ 'search_path='
  AND NOT EXISTS (SELECT 1 FROM pg_depend d
                  WHERE d.objid = p.oid AND d.classid = 'pg_proc'::regclass AND d.deptype = 'e')
ORDER BY n.nspname, p.proname;
\echo '@@END PG-SEC-014'

-- ======== PG-VAC-007  P100  Estimated table bloat over 30 percent (200 MB or more wasted) ========
\echo '@@CHECK PG-VAC-007'
-- check: PG-VAC-007
-- title: Estimated table bloat over 30 percent (200 MB or more wasted)
-- priority: 100
-- scope: relation
-- cost: 1
-- thresholds: bloat_pct, wasted_bytes, bloat_pct_high, wasted_bytes_high, top_n
-- estimator: lib/bloat_table.sql (re-derived from documented page layout; no third-party code)
WITH const AS (
  SELECT current_setting('block_size')::numeric AS bs,
         23::numeric AS tuple_hdr, 8::numeric AS ma,
         24::numeric AS page_hdr,  4::numeric AS item_id
),
colstats AS (
  SELECT s.schemaname, s.tablename,
         sum((1 - s.null_frac)::numeric * s.avg_width)    AS datawidth,
         count(*) FILTER (WHERE s.null_frac > 0) AS nullable_cols,
         count(*)                                AS ncols
  FROM pg_stats s
  WHERE s.schemaname NOT IN ('pg_catalog', 'information_schema')
  GROUP BY 1, 2
),
tbl AS (
  SELECT c.oid, n.nspname, c.relname, c.reltuples::numeric AS reltuples,
         c.relpages::numeric AS relpages, pg_relation_size(c.oid) AS rel_bytes,
         coalesce(substring(array_to_string(c.reloptions, ' ') FROM 'fillfactor=([0-9]+)')::numeric, 100) AS fillfactor
  FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE c.relkind IN ('r', 'm')
    AND n.nspname NOT IN ('pg_catalog', 'information_schema', 'pg_toast')
),
est AS (
  SELECT t.oid, t.nspname, t.relname, t.reltuples, t.relpages, t.rel_bytes, t.fillfactor,
         const.bs,
         ceil((const.tuple_hdr + CASE WHEN k.nullable_cols > 0 THEN ceil(k.ncols / 8.0) ELSE 0 END) / const.ma) * const.ma
           + ceil(coalesce(k.datawidth, 0) / const.ma) * const.ma AS tuple_bytes,
         greatest(1, floor(((const.bs - const.page_hdr) * t.fillfactor / 100.0)
                  / (ceil((const.tuple_hdr + CASE WHEN k.nullable_cols > 0 THEN ceil(k.ncols / 8.0) ELSE 0 END) / const.ma) * const.ma
                     + ceil(coalesce(k.datawidth, 0) / const.ma) * const.ma + const.item_id))) AS rows_per_page,
         (k.datawidth IS NULL OR t.reltuples < 0 OR t.relpages <= 0) AS is_na
  FROM tbl t
  LEFT JOIN colstats k ON k.schemaname = t.nspname AND k.tablename = t.relname
  CROSS JOIN const
),
scored AS (
  SELECT nspname, relname, reltuples, relpages, rel_bytes, fillfactor, tuple_bytes, rows_per_page,
         ceil(reltuples / rows_per_page)                            AS expected_pages,
         greatest(relpages - ceil(reltuples / rows_per_page), 0)    AS bloat_pages,
         (greatest(relpages - ceil(reltuples / rows_per_page), 0) * bs)::bigint AS bloat_bytes,
         round(100.0 * greatest(relpages - ceil(reltuples / rows_per_page), 0) / nullif(relpages, 0), 1) AS bloat_pct
  FROM est WHERE NOT is_na
)
SELECT 'PG-VAC-007'::text AS check_id,
       'relation'::text  AS scope,
       format('%I.%I.%I', current_database(), s.nspname, s.relname)::text AS object,
       format('Estimated %s%% bloat (threshold %s%%): %s of %s is space not occupied by live rows, against %s estimated live rows at %s bytes each and fillfactor %s. Estimated from pg_stats and pg_class only; confirm with pgstattuple_approx() before scheduling a rewrite.',
              s.bloat_pct::text, :'pg_vac_007_bloat_pct'::text,
              pg_size_pretty(s.bloat_bytes), pg_size_pretty(s.rel_bytes),
              to_char(s.reltuples::bigint, 'FM999,999,999,999'), s.tuple_bytes::text, s.fillfactor::text) AS details,
       json_build_object('bloat_pct', s.bloat_pct, 'bloat_bytes', s.bloat_bytes,
                         'relation_bytes', s.rel_bytes, 'relpages', s.relpages::bigint,
                         'expected_pages', s.expected_pages::bigint, 'reltuples', s.reltuples::bigint,
                         'estimated_tuple_bytes', s.tuple_bytes, 'fillfactor', s.fillfactor,
                         'threshold_pct', :'pg_vac_007_bloat_pct'::numeric,
                         'threshold_wasted_bytes', :'pg_vac_007_wasted_bytes'::bigint,
                         'estimator', 'lib/bloat_table.sql')::text AS evidence_json,
       'medium'::text AS confidence
FROM scored s
WHERE s.bloat_pct   >= :'pg_vac_007_bloat_pct'::numeric
  AND s.bloat_bytes >= :'pg_vac_007_wasted_bytes'::bigint
  AND NOT (s.bloat_pct >= :'pg_vac_007_bloat_pct_high'::numeric
           AND s.bloat_bytes >= :'pg_vac_007_wasted_bytes_high'::bigint)
ORDER BY s.bloat_bytes DESC
LIMIT :'pg_vac_007_top_n'::int;
\echo '@@END PG-VAC-007'

-- ======== PG-VAC-009  P100  Tables with autovacuum disabled via a storage parameter ========
\echo '@@CHECK PG-VAC-009'
-- check: PG-VAC-009
-- title: Tables with autovacuum disabled via a storage parameter
-- priority: 100
-- scope: relation
-- cost: 1
SELECT 'PG-VAC-009'::text AS check_id,
       'relation'::text   AS scope,
       format('%I.%I.%I', current_database(), n.nspname, c.relname)::text AS object,
       format('reloptions contain %s. Size %s, %s dead tuples against %s live. Last vacuum %s, last autovacuum %s. Nothing will reclaim dead tuples on this relation except a manual VACUUM or the emergency anti-wraparound path; relfrozenxid age is currently %s.',
              array_to_string(ARRAY(SELECT o FROM unnest(c.reloptions) o WHERE o LIKE 'autovacuum%'), ', '),
              pg_size_pretty(pg_total_relation_size(c.oid)),
              to_char(coalesce(t.n_dead_tup, 0), 'FM999,999,999,999'),
              to_char(coalesce(t.n_live_tup, 0), 'FM999,999,999,999'),
              coalesce(t.last_vacuum::text, 'never'), coalesce(t.last_autovacuum::text, 'never'),
              to_char(age(c.relfrozenxid), 'FM999,999,999,999')) AS details,
       json_build_object('reloptions', array_to_string(c.reloptions, ';'),
                         'total_bytes', pg_total_relation_size(c.oid),
                         'n_dead_tup', t.n_dead_tup, 'n_live_tup', t.n_live_tup,
                         'last_vacuum', t.last_vacuum, 'last_autovacuum', t.last_autovacuum,
                         'relfrozenxid_age', age(c.relfrozenxid))::text AS evidence_json,
       'high'::text AS confidence
FROM pg_class c
JOIN pg_namespace n ON n.oid = c.relnamespace
LEFT JOIN pg_stat_user_tables t ON t.relid = c.oid
WHERE c.relkind IN ('r', 'm', 'p')
  AND n.nspname NOT IN ('pg_catalog', 'information_schema', 'pg_toast')
  AND array_to_string(c.reloptions, ' ') ~ 'autovacuum_enabled\s*=\s*(false|off|0)'
ORDER BY pg_total_relation_size(c.oid) DESC;
\echo '@@END PG-VAC-009'

-- ======== PG-VAC-010  P100  Very large tables using the default vacuum scale factor ========
\echo '@@CHECK PG-VAC-010'
-- check: PG-VAC-010
-- title: Very large tables using the default vacuum scale factor
-- priority: 100
-- scope: relation
-- cost: 1
-- thresholds: min_tuples
SELECT 'PG-VAC-010'::text AS check_id,
       'relation'::text   AS scope,
       format('%I.%I.%I', current_database(), n.nspname, c.relname)::text AS object,
       format('Estimated %s rows (threshold %s), size %s, with no per-table autovacuum_vacuum_scale_factor or autovacuum_vacuum_threshold. At the cluster default scale factor of %s the table accumulates about %s dead tuples before autovacuum starts, and each of those runs then has to scan the whole relation.',
              to_char(c.reltuples::bigint, 'FM999,999,999,999'),
              to_char(:'pg_vac_010_min_tuples'::bigint, 'FM999,999,999,999'),
              pg_size_pretty(pg_total_relation_size(c.oid)),
              current_setting('autovacuum_vacuum_scale_factor'),
              to_char((c.reltuples * current_setting('autovacuum_vacuum_scale_factor')::numeric)::bigint, 'FM999,999,999,999')) AS details,
       json_build_object('reltuples', c.reltuples::bigint,
                         'threshold_tuples', :'pg_vac_010_min_tuples'::bigint,
                         'total_bytes', pg_total_relation_size(c.oid),
                         'cluster_scale_factor', current_setting('autovacuum_vacuum_scale_factor')::numeric,
                         'reloptions', array_to_string(c.reloptions, ';'))::text AS evidence_json,
       'medium'::text AS confidence
FROM pg_class c
JOIN pg_namespace n ON n.oid = c.relnamespace
WHERE c.relkind IN ('r', 'm')
  AND n.nspname NOT IN ('pg_catalog', 'information_schema', 'pg_toast')
  AND c.reltuples >= :'pg_vac_010_min_tuples'::bigint
  AND coalesce(array_to_string(c.reloptions, ' '), '') !~ 'autovacuum_vacuum_(scale_factor|threshold)'
ORDER BY c.reltuples DESC;
\echo '@@END PG-VAC-010'

-- ======== PG-VAC-013  P100  Insert-only tables never vacuumed (PostgreSQL 12 and older) ========
SELECT (current_setting('server_version_num')::int < 130000) AS gate_pg_vac_013 \gset
\if :gate_pg_vac_013
\echo '@@CHECK PG-VAC-013'
-- check: PG-VAC-013
-- title: Insert-only tables never vacuumed (PostgreSQL 12 and older)
-- priority: 100
-- scope: relation
-- cost: 1
-- max_version: 12
-- thresholds: min_inserts
SELECT 'PG-VAC-013'::text AS check_id,
       'relation'::text   AS scope,
       format('%I.%I.%I', current_database(), t.schemaname, t.relname)::text AS object,
       format('%s inserts (threshold %s), no updates and no deletes, never vacuumed, size %s. On PostgreSQL %s autovacuum does not consider inserts at all (autovacuum_vacuum_insert_threshold arrived in 13), so this relation has no visibility map: index-only scans always visit the heap, and the pages will only ever be frozen by the emergency anti-wraparound vacuum. relfrozenxid age is %s.',
              to_char(t.n_tup_ins, 'FM999,999,999,999'),
              to_char(:'pg_vac_013_min_inserts'::bigint, 'FM999,999,999,999'),
              pg_size_pretty(pg_total_relation_size(t.relid)),
              current_setting('server_version'),
              to_char(age(c.relfrozenxid), 'FM999,999,999,999')) AS details,
       json_build_object('n_tup_ins', t.n_tup_ins, 'n_tup_upd', t.n_tup_upd, 'n_tup_del', t.n_tup_del,
                         'threshold_inserts', :'pg_vac_013_min_inserts'::bigint,
                         'total_bytes', pg_total_relation_size(t.relid),
                         'relfrozenxid_age', age(c.relfrozenxid))::text AS evidence_json,
       'high'::text AS confidence
FROM pg_stat_user_tables t
JOIN pg_class c ON c.oid = t.relid
WHERE t.n_tup_ins >= :'pg_vac_013_min_inserts'::bigint
  AND t.n_tup_upd = 0 AND t.n_tup_del = 0
  AND t.last_vacuum IS NULL AND t.last_autovacuum IS NULL
ORDER BY t.n_tup_ins DESC;
\echo '@@END PG-VAC-013'
\else
\echo '@@SKIP PG-VAC-013 only applies to PostgreSQL 12 and older'
\endif

-- ======== PG-IDX-003  P150  Unused index (small, or usage statistics too young) ========
\echo '@@CHECK PG-IDX-003'
-- check: PG-IDX-003
-- title: Unused index (small, or usage statistics too young)
-- priority: 150
-- scope: index
-- cost: 1
-- thresholds: min_bytes, big_bytes, stats_age_days, top_n
WITH win AS (
  SELECT greatest(extract(epoch FROM now() - coalesce(
           (SELECT min(stats_reset) FROM pg_stat_database WHERE datname = current_database()),
           pg_postmaster_start_time())) / 86400.0, 0.01) AS days
)
SELECT 'PG-IDX-003'::text AS check_id,
       'index'::text    AS scope,
       format('%I.%I.%I', current_database(), s.schemaname, s.indexrelname)::text AS object,
       format('Index %s on %s.%s has been scanned 0 times in %s days of collected statistics (threshold: size >= %s%s). Size %s, table %s, %s writes to the table since the reset - every one of those maintained this index for nothing. Definition: %s. Usage counters are per instance: an index unused here may be serving a read replica, so verify on every standby before dropping. The reversible first step is ALTER INDEX %s.%s SET (deprecated) - there is no such option, so in practice: drop it in a transaction you are prepared to roll back, or rename it and watch for errors, then DROP INDEX CONCURRENTLY.',
              s.indexrelname, s.schemaname, s.relname,
              round(w.days, 1)::text,
              pg_size_pretty(:'pg_idx_003_min_bytes'::bigint), '',
              pg_size_pretty(pg_relation_size(s.indexrelid)),
              pg_size_pretty(pg_relation_size(s.relid)),
              to_char(coalesce(t.n_tup_ins + t.n_tup_upd + t.n_tup_del, 0), 'FM999,999,999,999'),
              pg_get_indexdef(s.indexrelid),
              quote_ident(s.schemaname), quote_ident(s.indexrelname)) AS details,
       json_build_object('schema', s.schemaname, 'table', s.relname, 'index', s.indexrelname,
                         'idx_scan', s.idx_scan,
                         'index_bytes', pg_relation_size(s.indexrelid),
                         'table_bytes', pg_relation_size(s.relid),
                         'threshold_bytes', :'pg_idx_003_min_bytes'::bigint,
                         'stats_window_days', round(w.days, 2),
                         'table_writes', coalesce(t.n_tup_ins + t.n_tup_upd + t.n_tup_del, 0),
                         'indexdef', pg_get_indexdef(s.indexrelid),
                         'indisunique', i.indisunique, 'indisprimary', i.indisprimary)::text AS evidence_json,
       CASE WHEN w.days < :'pg_idx_003_stats_age_days'::numeric THEN 'low' ELSE 'medium' END::text AS confidence
FROM pg_stat_user_indexes s
JOIN pg_index i           ON i.indexrelid = s.indexrelid
LEFT JOIN pg_stat_user_tables t ON t.relid = s.relid
CROSS JOIN win w
WHERE s.idx_scan = 0
  AND NOT i.indisunique AND NOT i.indisprimary AND NOT i.indisreplident
  AND i.indisvalid
  AND NOT EXISTS (SELECT 1 FROM pg_constraint con WHERE con.conindid = s.indexrelid)
  AND pg_relation_size(s.indexrelid) >= :'pg_idx_003_min_bytes'::bigint
  AND NOT (pg_relation_size(s.indexrelid) >= :'pg_idx_003_big_bytes'::bigint
           AND w.days >= :'pg_idx_003_stats_age_days'::numeric)
ORDER BY pg_relation_size(s.indexrelid) DESC
LIMIT :'pg_idx_003_top_n'::int;
\echo '@@END PG-IDX-003'

-- ======== PG-IDX-007  P150  Estimated B-tree bloat over 30 percent (100 MB or more wasted) ========
\echo '@@CHECK PG-IDX-007'
-- check: PG-IDX-007
-- title: Estimated B-tree bloat over 30 percent (100 MB or more wasted)
-- priority: 150
-- scope: index
-- cost: 1
-- thresholds: bloat_pct, wasted_bytes, bloat_pct_high, wasted_bytes_high, top_n
-- estimator: lib/bloat_btree.sql (re-derived from documented page layout; no third-party code)
WITH const AS (
  SELECT current_setting('block_size')::numeric AS bs,
         8::numeric AS index_tuple_hdr, 8::numeric AS ma,
         24::numeric AS page_hdr, 16::numeric AS btree_special, 4::numeric AS item_id
),
idx AS (
  SELECT i.indexrelid, i.indrelid, ic.relname AS index_name, tn.nspname, tc.relname AS table_name,
         ic.reltuples::numeric AS reltuples, ic.relpages::numeric AS relpages,
         pg_relation_size(i.indexrelid) AS index_bytes,
         i.indnatts, i.indnkeyatts, i.indkey,
         (i.indexprs IS NOT NULL OR i.indpred IS NOT NULL) AS is_special,
         coalesce(substring(array_to_string(ic.reloptions, ' ') FROM 'fillfactor=([0-9]+)')::numeric, 90) AS fillfactor
  FROM pg_index i
  JOIN pg_class ic ON ic.oid = i.indexrelid
  JOIN pg_class tc ON tc.oid = i.indrelid
  JOIN pg_namespace tn ON tn.oid = tc.relnamespace
  JOIN pg_am am ON am.oid = ic.relam AND am.amname = 'btree'
  WHERE tn.nspname NOT IN ('pg_catalog', 'information_schema', 'pg_toast')
    AND i.indisvalid
),
keywidth AS (
  SELECT x.indexrelid,
         sum((1 - s.null_frac)::numeric * s.avg_width)    AS keywidth,
         count(*) FILTER (WHERE s.null_frac > 0) AS nullable_cols,
         count(*)                                AS ncols
  FROM (SELECT idx.indexrelid, idx.nspname, idx.table_name, a.attname
        FROM idx
        JOIN LATERAL unnest(idx.indkey[0:idx.indnkeyatts - 1]) WITH ORDINALITY AS k(attnum, ord) ON true
        JOIN pg_attribute a ON a.attrelid = idx.indrelid AND a.attnum = k.attnum
        WHERE NOT idx.is_special) x
  JOIN pg_stats s ON s.schemaname = x.nspname AND s.tablename = x.table_name AND s.attname = x.attname
  GROUP BY 1
),
est AS (
  SELECT idx.*, const.bs,
         ceil((const.index_tuple_hdr + CASE WHEN kw.nullable_cols > 0 THEN ceil(kw.ncols / 8.0) ELSE 0 END) / const.ma) * const.ma
           + ceil(coalesce(kw.keywidth, 0) / const.ma) * const.ma AS entry_bytes,
         greatest(1, floor(((const.bs - const.page_hdr - const.btree_special) * idx.fillfactor / 100.0)
                  / (ceil((const.index_tuple_hdr + CASE WHEN kw.nullable_cols > 0 THEN ceil(kw.ncols / 8.0) ELSE 0 END) / const.ma) * const.ma
                     + ceil(coalesce(kw.keywidth, 0) / const.ma) * const.ma + const.item_id))) AS entries_per_page,
         (idx.is_special OR kw.keywidth IS NULL OR idx.reltuples < 0 OR idx.relpages <= 1) AS is_na
  FROM idx LEFT JOIN keywidth kw ON kw.indexrelid = idx.indexrelid CROSS JOIN const
),
scored AS (
  SELECT nspname, table_name, index_name, reltuples, relpages, index_bytes, fillfactor,
         entry_bytes, entries_per_page,
         greatest(relpages - ceil(reltuples / entries_per_page), 0) AS bloat_pages,
         (greatest(relpages - ceil(reltuples / entries_per_page), 0) * bs)::bigint AS bloat_bytes,
         round(100.0 * greatest(relpages - ceil(reltuples / entries_per_page), 0) / nullif(relpages, 0), 1) AS bloat_pct
  FROM est WHERE NOT is_na
)
SELECT 'PG-IDX-007'::text AS check_id,
       'index'::text     AS scope,
       format('%I.%I.%I', current_database(), s.nspname, s.index_name)::text AS object,
       format('Estimated %s%% bloat (threshold %s%%) on index %s of table %s: %s of %s is not occupied by live entries, against %s estimated entries at %s bytes each and fillfactor %s. Estimated from pg_stats and pg_class only. REINDEX INDEX CONCURRENTLY rebuilds it without blocking writes on PostgreSQL 12 and newer.',
              s.bloat_pct::text, :'pg_idx_007_bloat_pct'::text, s.index_name, s.table_name,
              pg_size_pretty(s.bloat_bytes), pg_size_pretty(s.index_bytes),
              to_char(s.reltuples::bigint, 'FM999,999,999,999'), s.entry_bytes::text, s.fillfactor::text) AS details,
       json_build_object('bloat_pct', s.bloat_pct, 'bloat_bytes', s.bloat_bytes,
                         'index_bytes', s.index_bytes, 'relpages', s.relpages::bigint,
                         'reltuples', s.reltuples::bigint, 'estimated_entry_bytes', s.entry_bytes,
                         'fillfactor', s.fillfactor, 'table', s.table_name,
                         'threshold_pct', :'pg_idx_007_bloat_pct'::numeric,
                         'threshold_wasted_bytes', :'pg_idx_007_wasted_bytes'::bigint,
                         'estimator', 'lib/bloat_btree.sql')::text AS evidence_json,
       'medium'::text AS confidence
FROM scored s
WHERE s.bloat_pct   >= :'pg_idx_007_bloat_pct'::numeric
  AND s.bloat_bytes >= :'pg_idx_007_wasted_bytes'::bigint
  AND NOT (s.bloat_pct >= :'pg_idx_007_bloat_pct_high'::numeric
           AND s.bloat_bytes >= :'pg_idx_007_wasted_bytes_high'::bigint)
ORDER BY s.bloat_bytes DESC
LIMIT :'pg_idx_007_top_n'::int;
\echo '@@END PG-IDX-007'

-- ======== PG-IDX-009  P150  Unindexed foreign key (small table) ========
\echo '@@CHECK PG-IDX-009'
-- check: PG-IDX-009
-- title: Unindexed foreign key (small table)
-- priority: 150
-- scope: relation
-- cost: 1
-- thresholds: min_bytes, parent_writes, top_n
WITH fk AS (
  SELECT con.oid AS conoid, con.conname, con.conrelid, con.confrelid, con.conkey,
         cn.nspname AS child_schema, cc.relname AS child_table,
         pn.nspname AS parent_schema, pc.relname AS parent_table,
         pg_relation_size(con.conrelid) AS child_bytes,
         coalesce(pt.n_tup_del + pt.n_tup_upd, 0) AS parent_writes,
         (SELECT string_agg(a.attname, ', ' ORDER BY k.ord)
          FROM unnest(con.conkey) WITH ORDINALITY AS k(attnum, ord)
          JOIN pg_attribute a ON a.attrelid = con.conrelid AND a.attnum = k.attnum) AS child_columns
  FROM pg_constraint con
  JOIN pg_class cc      ON cc.oid = con.conrelid
  JOIN pg_namespace cn  ON cn.oid = cc.relnamespace
  JOIN pg_class pc      ON pc.oid = con.confrelid
  JOIN pg_namespace pn  ON pn.oid = pc.relnamespace
  LEFT JOIN pg_stat_user_tables pt ON pt.relid = con.confrelid
  WHERE con.contype = 'f'
    AND cn.nspname NOT IN ('pg_catalog', 'information_schema', 'pg_toast')
),
unindexed AS (
  SELECT fk.* FROM fk
  WHERE NOT EXISTS (
    SELECT 1 FROM pg_index i
    WHERE i.indrelid = fk.conrelid AND i.indisvalid
      AND (string_to_array(i.indkey::text, ' '))[1:cardinality(fk.conkey)]
          = (SELECT array_agg(x::text ORDER BY o) FROM unnest(fk.conkey) WITH ORDINALITY AS u(x, o))
  )
)
SELECT 'PG-IDX-009'::text AS check_id,
       'relation'::text AS scope,
       format('%I.%I.%I', current_database(), u.child_schema, u.child_table)::text AS object,
       format('Foreign key %s on %s.%s (%s) references %s.%s and has no index whose leading columns match it. Child table %s, parent has had %s updates and deletes since the statistics reset. Every DELETE or key UPDATE on the parent has to sequentially scan the child under a lock to check the constraint, and ON DELETE CASCADE makes that scan happen per parent row. Thresholds: child size >= %s or parent writes >= %s. Fix: CREATE INDEX CONCURRENTLY ON %s.%s (%s).',
              u.conname, u.child_schema, u.child_table, u.child_columns,
              u.parent_schema, u.parent_table,
              pg_size_pretty(u.child_bytes),
              to_char(u.parent_writes, 'FM999,999,999,999'),
              pg_size_pretty(:'pg_idx_009_min_bytes'::bigint),
              to_char(:'pg_idx_009_parent_writes'::bigint, 'FM999,999,999,999'),
              quote_ident(u.child_schema), quote_ident(u.child_table), u.child_columns) AS details,
       json_build_object('constraint', u.conname,
                         'child_schema', u.child_schema, 'child_table', u.child_table,
                         'child_columns', u.child_columns,
                         'parent_schema', u.parent_schema, 'parent_table', u.parent_table,
                         'child_bytes', u.child_bytes, 'parent_writes', u.parent_writes,
                         'threshold_child_bytes', :'pg_idx_009_min_bytes'::bigint,
                         'threshold_parent_writes', :'pg_idx_009_parent_writes'::bigint)::text AS evidence_json,
       'high'::text AS confidence
FROM unindexed u
WHERE u.child_bytes < :'pg_idx_009_min_bytes'::bigint
    AND u.parent_writes < :'pg_idx_009_parent_writes'::bigint
ORDER BY u.child_bytes DESC
LIMIT :'pg_idx_009_top_n'::int;
\echo '@@END PG-IDX-009'

-- ======== PG-IDX-011  P150  Sequential scans on mid-size tables ========
\echo '@@CHECK PG-IDX-011'
-- check: PG-IDX-011
-- title: Sequential scans on mid-size tables
-- priority: 150
-- scope: relation
-- cost: 1
-- thresholds: min_bytes, max_bytes, min_seq_scans, rows_per_scan, seq_fraction, top_n
SELECT 'PG-IDX-011'::text AS check_id,
       'relation'::text AS scope,
       format('%I.%I.%I', current_database(), t.schemaname, t.relname)::text AS object,
       format('Table %s.%s (%s) has had %s sequential scans and %s index scans since the statistics reset, reading an average of %s rows per sequential scan. Sequential scans are %s%% of all scans (thresholds: size %s, %s scans, %s rows per scan, %s%% of scans). Something queries this table without a usable index, or with a predicate the planner cannot use. Confidence is medium: a nightly export or an analytics job legitimately reads the whole table, and this counter cannot tell those apart from a missing index. PG-QRY-003 and PG-QRY-005 show which statements dominate.',
              t.schemaname, t.relname,
              pg_size_pretty(pg_relation_size(t.relid)),
              to_char(t.seq_scan, 'FM999,999,999,999'),
              to_char(coalesce(t.idx_scan, 0), 'FM999,999,999,999'),
              to_char(round(t.seq_tup_read::numeric / nullif(t.seq_scan, 0)), 'FM999,999,999,999'),
              round(100.0 * t.seq_scan / nullif(t.seq_scan + coalesce(t.idx_scan, 0), 0), 1)::text,
              pg_size_pretty(:'pg_idx_011_min_bytes'::bigint),
              :'pg_idx_011_min_seq_scans'::text,
              to_char(:'pg_idx_011_rows_per_scan'::bigint, 'FM999,999,999,999'),
              round(100 * :'pg_idx_011_seq_fraction'::numeric)::text) AS details,
       json_build_object('schema', t.schemaname, 'table', t.relname,
                         'seq_scan', t.seq_scan, 'idx_scan', coalesce(t.idx_scan, 0),
                         'seq_tup_read', t.seq_tup_read,
                         'rows_per_seq_scan', round(t.seq_tup_read::numeric / nullif(t.seq_scan, 0))::bigint,
                         'seq_fraction', round(t.seq_scan::numeric / nullif(t.seq_scan + coalesce(t.idx_scan, 0), 0), 4),
                         'relation_bytes', pg_relation_size(t.relid),
                         'index_count', (SELECT count(*) FROM pg_index i WHERE i.indrelid = t.relid),
                         'threshold_bytes', :'pg_idx_011_min_bytes'::bigint,
                         'threshold_seq_scans', :'pg_idx_011_min_seq_scans'::bigint,
                         'threshold_rows_per_scan', :'pg_idx_011_rows_per_scan'::bigint,
                         'threshold_seq_fraction', :'pg_idx_011_seq_fraction'::numeric)::text AS evidence_json,
       'medium'::text AS confidence
FROM pg_stat_user_tables t
WHERE pg_relation_size(t.relid) >= :'pg_idx_011_min_bytes'::bigint
  AND pg_relation_size(t.relid) <  :'pg_idx_011_max_bytes'::bigint
  AND t.seq_scan >= :'pg_idx_011_min_seq_scans'::bigint
  AND t.seq_tup_read::numeric / nullif(t.seq_scan, 0) >= :'pg_idx_011_rows_per_scan'::bigint
  AND t.seq_scan::numeric / nullif(t.seq_scan + coalesce(t.idx_scan, 0), 0) >= :'pg_idx_011_seq_fraction'::numeric
ORDER BY t.seq_tup_read DESC
LIMIT :'pg_idx_011_top_n'::int;
\echo '@@END PG-IDX-011'

-- ======== PG-IDX-013  P150  Index footprint more than twice the heap on a large table ========
\echo '@@CHECK PG-IDX-013'
-- check: PG-IDX-013
-- title: Index footprint more than twice the heap on a large table
-- priority: 150
-- scope: relation
-- cost: 1
-- thresholds: min_bytes, index_multiple
SELECT 'PG-IDX-013'::text AS check_id,
       'relation'::text   AS scope,
       format('%I.%I.%I', current_database(), n.nspname, c.relname)::text AS object,
       format('Table %s.%s has %s of indexes against %s of heap (%sx, threshold %sx) across %s indexes. That is not wrong on its own - a covering index or a wide composite key legitimately costs this - but it is the shape that PG-IDX-002 (unused), PG-IDX-004 (duplicate), PG-IDX-005 (overlapping) and PG-IDX-006 (bloated) usually produce together. %s of the indexes have never been scanned. Largest three: %s.',
              n.nspname, c.relname,
              pg_size_pretty(pg_indexes_size(c.oid)), pg_size_pretty(pg_table_size(c.oid)),
              round(pg_indexes_size(c.oid)::numeric / nullif(pg_table_size(c.oid), 0), 1)::text,
              :'pg_idx_013_index_multiple'::text,
              (SELECT count(*) FROM pg_index i WHERE i.indrelid = c.oid AND i.indisvalid),
              (SELECT count(*) FROM pg_index i
               LEFT JOIN pg_stat_user_indexes si ON si.indexrelid = i.indexrelid
               WHERE i.indrelid = c.oid AND i.indisvalid AND coalesce(si.idx_scan, 0) = 0),
              coalesce((SELECT string_agg(format('%s (%s)', ic.relname, pg_size_pretty(pg_relation_size(ic.oid))), ', ')
                        FROM (SELECT ic2.oid, ic2.relname FROM pg_index i2
                              JOIN pg_class ic2 ON ic2.oid = i2.indexrelid
                              WHERE i2.indrelid = c.oid AND i2.indisvalid
                              ORDER BY pg_relation_size(ic2.oid) DESC LIMIT 3) ic), 'none')) AS details,
       json_build_object('schema', n.nspname, 'table', c.relname,
                         'table_bytes', pg_table_size(c.oid),
                         'indexes_bytes', pg_indexes_size(c.oid),
                         'index_multiple', round(pg_indexes_size(c.oid)::numeric / nullif(pg_table_size(c.oid), 0), 2),
                         'threshold_multiple', :'pg_idx_013_index_multiple'::numeric,
                         'threshold_bytes', :'pg_idx_013_min_bytes'::bigint,
                         'index_count', (SELECT count(*) FROM pg_index i WHERE i.indrelid = c.oid AND i.indisvalid))::text AS evidence_json,
       'high'::text AS confidence
FROM pg_class c
JOIN pg_namespace n ON n.oid = c.relnamespace
WHERE c.relkind IN ('r', 'm')
  AND n.nspname NOT IN ('pg_catalog', 'information_schema', 'pg_toast')
  AND pg_table_size(c.oid) >= :'pg_idx_013_min_bytes'::bigint
  AND pg_indexes_size(c.oid) >= :'pg_idx_013_index_multiple'::numeric * pg_table_size(c.oid)
ORDER BY pg_indexes_size(c.oid) DESC;
\echo '@@END PG-IDX-013'

-- ======== PG-IDX-014  P150  Wide B-tree indexes ========
SELECT (current_setting('server_version_num')::int >= 110000) AS gate_pg_idx_014 \gset
\if :gate_pg_idx_014
\echo '@@CHECK PG-IDX-014'
-- check: PG-IDX-014
-- title: Wide B-tree indexes
-- priority: 150
-- scope: index
-- cost: 1
-- min_version: 11
-- thresholds: min_key_columns, min_bytes
SELECT 'PG-IDX-014'::text AS check_id,
       'index'::text      AS scope,
       format('%I.%I.%I', current_database(), n.nspname, ic.relname)::text AS object,
       format('Index %s on %s.%s has %s key columns (threshold %s) and occupies %s. Every key column appears in every leaf entry and in every internal page, so the index is wide, its fan-out is low and its depth is higher than it needs to be. Only queries whose predicate matches a leading prefix can use it, which is what PG-IDX-005 looks for from the other side. Recorded scans: %s. Definition: %s. If the trailing columns are only there to make the index covering, INCLUDE columns (PostgreSQL 11 and newer) give the same benefit without widening the key.',
              ic.relname, n.nspname, tc.relname, i.indnkeyatts,
              :'pg_idx_014_min_key_columns'::text,
              pg_size_pretty(pg_relation_size(i.indexrelid)),
              coalesce(s.idx_scan::text, 'unknown'),
              pg_get_indexdef(i.indexrelid)) AS details,
       json_build_object('schema', n.nspname, 'table', tc.relname, 'index', ic.relname,
                         'key_columns', i.indnkeyatts, 'total_columns', i.indnatts,
                         'index_bytes', pg_relation_size(i.indexrelid),
                         'idx_scan', s.idx_scan,
                         'threshold_key_columns', :'pg_idx_014_min_key_columns'::int,
                         'threshold_bytes', :'pg_idx_014_min_bytes'::bigint,
                         'indexdef', pg_get_indexdef(i.indexrelid))::text AS evidence_json,
       'high'::text AS confidence
FROM pg_index i
JOIN pg_class ic    ON ic.oid = i.indexrelid
JOIN pg_class tc    ON tc.oid = i.indrelid
JOIN pg_namespace n ON n.oid = ic.relnamespace
JOIN pg_am am       ON am.oid = ic.relam AND am.amname = 'btree'
LEFT JOIN pg_stat_user_indexes s ON s.indexrelid = i.indexrelid
WHERE i.indisvalid
  AND n.nspname NOT IN ('pg_catalog', 'information_schema', 'pg_toast')
  AND i.indnkeyatts >= :'pg_idx_014_min_key_columns'::int
  AND pg_relation_size(i.indexrelid) >= :'pg_idx_014_min_bytes'::bigint
ORDER BY pg_relation_size(i.indexrelid) DESC;
\echo '@@END PG-IDX-014'
\else
\echo '@@SKIP PG-IDX-014 needs PostgreSQL 11 or newer'
\endif

-- ======== PG-IDX-015  P150  Single-column index on a very low-cardinality column ========
\echo '@@CHECK PG-IDX-015'
-- check: PG-IDX-015
-- title: Single-column index on a very low-cardinality column
-- priority: 150
-- scope: index
-- cost: 1
-- thresholds: max_distinct, min_bytes
SELECT 'PG-IDX-015'::text AS check_id,
       'index'::text      AS scope,
       format('%I.%I.%I', current_database(), n.nspname, ic.relname)::text AS object,
       format('Index %s on %s.%s(%s) covers a column with only %s distinct values, on a table of %s. An index whose most common value covers %s%% of the table cannot help the planner for that value - a sequential scan is cheaper - so it earns its keep only for the rare values. Index size %s, recorded scans %s. If the queries always filter for one particular value, a partial index (CREATE INDEX ... WHERE col = ...) is a fraction of the size and is maintained only for the rows that match.',
              ic.relname, n.nspname, tc.relname, st.attname,
              st.n_distinct::text,
              pg_size_pretty(pg_relation_size(i.indrelid)),
              round(100 * coalesce(st.most_common_freqs[1], 0))::text,
              pg_size_pretty(pg_relation_size(i.indexrelid)),
              coalesce(s.idx_scan::text, 'unknown')) AS details,
       json_build_object('schema', n.nspname, 'table', tc.relname, 'index', ic.relname,
                         'column', st.attname, 'n_distinct', st.n_distinct,
                         'most_common_freq', st.most_common_freqs[1],
                         'index_bytes', pg_relation_size(i.indexrelid),
                         'table_bytes', pg_relation_size(i.indrelid),
                         'idx_scan', s.idx_scan,
                         'threshold_distinct', :'pg_idx_015_max_distinct'::numeric,
                         'threshold_bytes', :'pg_idx_015_min_bytes'::bigint)::text AS evidence_json,
       'medium'::text AS confidence
FROM pg_index i
JOIN pg_class ic    ON ic.oid = i.indexrelid
JOIN pg_class tc    ON tc.oid = i.indrelid
JOIN pg_namespace n ON n.oid = tc.relnamespace
JOIN pg_am am       ON am.oid = ic.relam AND am.amname = 'btree'
JOIN pg_attribute a ON a.attrelid = i.indrelid AND a.attnum = i.indkey[0]
JOIN pg_stats st    ON st.schemaname = n.nspname AND st.tablename = tc.relname AND st.attname = a.attname
LEFT JOIN pg_stat_user_indexes s ON s.indexrelid = i.indexrelid
WHERE i.indisvalid AND i.indnatts = 1 AND i.indexprs IS NULL AND i.indpred IS NULL
  AND NOT i.indisunique AND NOT i.indisprimary
  AND n.nspname NOT IN ('pg_catalog', 'information_schema', 'pg_toast')
  AND st.n_distinct > 0 AND st.n_distinct <= :'pg_idx_015_max_distinct'::numeric
  AND pg_relation_size(i.indrelid) >= :'pg_idx_015_min_bytes'::bigint
ORDER BY pg_relation_size(i.indexrelid) DESC;
\echo '@@END PG-IDX-015'

-- ======== PG-QRY-010  P150  Plan-hostile patterns in top statements ========
\echo '@@CHECK PG-QRY-010'
-- check: PG-QRY-010
-- title: Plan-hostile patterns in top statements
-- priority: 150
-- scope: query
-- cost: 1
-- thresholds: top_n, offset_rows
-- Regular expressions over normalised statement text. Every hit is a candidate,
-- not a defect: confidence is low by construction and this check never appears
-- in "Fix first".
\set ON_ERROR_STOP off
SELECT (to_regclass('pg_stat_statements') IS NOT NULL) AS pg_qry_010_pgss \gset
\if :pg_qry_010_pgss
SELECT EXISTS (SELECT 1 FROM pg_attribute
               WHERE attrelid = to_regclass('pg_stat_statements')
                 AND attname = 'total_exec_time' AND NOT attisdropped) AS pg_qry_010_v18 \gset
WITH q AS (
\if :pg_qry_010_v18
  SELECT queryid, query, calls, total_exec_time::numeric AS total_ms
  FROM pg_stat_statements WHERE dbid = (SELECT oid FROM pg_database WHERE datname = current_database())
  ORDER BY total_exec_time DESC LIMIT :'pg_qry_010_top_n'::int
\else
  SELECT queryid, query, calls, total_time::numeric AS total_ms
  FROM pg_stat_statements WHERE dbid = (SELECT oid FROM pg_database WHERE datname = current_database())
  ORDER BY total_time DESC LIMIT :'pg_qry_010_top_n'::int
\endif
),
flagged AS (
  SELECT q.*, p.pattern, p.explanation
  FROM q
  CROSS JOIN LATERAL (VALUES
    ('leading-wildcard LIKE',
     'A LIKE or ILIKE pattern that begins with % cannot use a B-tree index at all; a trigram index (pg_trgm) or full-text search is the usual answer. Note that pg_stat_statements replaces literals with $n, so a pattern supplied as a bound parameter is invisible here: this fires only where the wildcard is written into the SQL or concatenated in it.',
     q.query ~* 'i?like\s+(''%|''\s*\|\||concat\s*\(\s*''%)'),
    ('NOT IN (SELECT ...)',
     'NOT IN over a subquery that can produce NULL returns no rows at all, and the planner cannot turn it into an anti-join. NOT EXISTS is both correct with NULLs and plannable.',
     q.query ~* 'not\s+in\s*\(\s*select'),
    ('ORDER BY random()',
     'ORDER BY random() sorts the entire result set to return a few rows. TABLESAMPLE, or a random key lookup, does the same job without the sort.',
     q.query ~* 'order\s+by\s+random\s*\('),
    ('large OFFSET',
     'A large OFFSET makes the server produce and discard every skipped row on every page. Keyset pagination (WHERE key > last_seen ORDER BY key LIMIT n) reads only what it returns.',
     q.query ~* 'offset\s+\$?[0-9]{5,}'),
    ('function on an indexed column in WHERE',
     'Wrapping a column in lower(), upper() or a cast inside WHERE prevents a plain index on that column from being used; only a matching expression index helps.',
     q.query ~* 'where[^;]*\b(lower|upper)\s*\(\s*[a-z_][a-z0-9_.]*\s*\)\s*(=|like)'),
    ('unfiltered count(*)',
     'count(*) with no WHERE has to visit every row (or every visibility-map page); on a large table that cost is paid on every call.',
     q.query ~* '^\s*select\s+count\s*\(\s*\*\s*\)\s+from\s+[a-z_"][a-z0-9_."]*\s*(;|$)'),
    ('SELECT *',
     'SELECT * ships every column, defeats index-only scans, and breaks silently when the table gains a column.',
     q.query ~* '^\s*select\s+\*\s+from')
  ) AS p(pattern, explanation, matched)
  WHERE p.matched
)
SELECT 'PG-QRY-010'::text AS check_id,
       'query'::text      AS scope,
       ('queryid:' || f.queryid::text)::text AS object,
       format('Pattern "%s" found in a top-%s statement by total time (%s ms over %s calls). %s This is a regular expression over normalised statement text, so it is a candidate to read, not a defect: the pattern may be correct here, and the regex may have misread the statement. Statement: %s',
              f.pattern, :'pg_qry_010_top_n'::text,
              to_char(round(f.total_ms), 'FM999,999,999,999'),
              to_char(f.calls, 'FM999,999,999,999'),
              f.explanation,
              left(regexp_replace(f.query, '\s+', ' ', 'g'), 300)) AS details,
       json_build_object('queryid', f.queryid, 'pattern', f.pattern,
                         'calls', f.calls, 'total_ms', round(f.total_ms, 2),
                         'detection', 'regex over normalised query text',
                         'query', left(regexp_replace(f.query, '\s+', ' ', 'g'), 300))::text AS evidence_json,
       'low'::text AS confidence
FROM flagged f
ORDER BY f.total_ms DESC;
\endif
\echo '@@END PG-QRY-010'

-- ======== PG-QRY-013  P150  Plan-instability candidates (high standard deviation) ========
\echo '@@CHECK PG-QRY-013'
-- check: PG-QRY-013
-- title: Plan-instability candidates (high standard deviation)
-- priority: 150
-- scope: query
-- cost: 1
-- thresholds: stddev_multiple, min_calls, min_mean_ms, top_n
\set ON_ERROR_STOP off
SELECT (to_regclass('pg_stat_statements') IS NOT NULL) AS pg_qry_013_pgss \gset
\if :pg_qry_013_pgss
SELECT EXISTS (SELECT 1 FROM pg_attribute
               WHERE attrelid = to_regclass('pg_stat_statements')
                 AND attname = 'total_exec_time' AND NOT attisdropped) AS pg_qry_013_v18 \gset
WITH q AS (
\if :pg_qry_013_v18
  SELECT queryid, query, calls, rows,
         total_exec_time::numeric AS total_ms, mean_exec_time::numeric AS mean_ms,
         stddev_exec_time::numeric AS stddev_ms,
         shared_blks_read, shared_blks_hit, temp_blks_read, temp_blks_written, userid
  FROM pg_stat_statements WHERE dbid = (SELECT oid FROM pg_database WHERE datname = current_database())
\else
  SELECT queryid, query, calls, rows,
         total_time::numeric AS total_ms, mean_time::numeric AS mean_ms,
         stddev_time::numeric AS stddev_ms,
         shared_blks_read, shared_blks_hit, temp_blks_read, temp_blks_written, userid
  FROM pg_stat_statements WHERE dbid = (SELECT oid FROM pg_database WHERE datname = current_database())
\endif
),
tot AS (SELECT sum(total_ms) AS all_ms, sum(calls) AS all_calls FROM q)

SELECT 'PG-QRY-013'::text AS check_id,
       'query'::text      AS scope,
       ('queryid:' || q.queryid::text)::text AS object,
       format('Execution time for this statement has a standard deviation of %s ms against a mean of %s ms (%sx, threshold %sx) over %s calls. A spread that wide means the same normalised statement sometimes runs quickly and sometimes does not: parameter values that select very different row counts, a generic plan chosen after five executions of a prepared statement, or a working set that is sometimes cached and sometimes not. The mean and the "top by total time" ranking both hide this. Total %s ms, %s rows per call. Statement: %s',
              round(q.stddev_ms, 2)::text, round(q.mean_ms, 2)::text,
              round(q.stddev_ms / nullif(q.mean_ms, 0), 1)::text,
              :'pg_qry_013_stddev_multiple'::text,
              to_char(q.calls, 'FM999,999,999,999'),
              to_char(round(q.total_ms), 'FM999,999,999,999'),
              round(q.rows::numeric / nullif(q.calls, 0), 1)::text,
              left(regexp_replace(q.query, '\s+', ' ', 'g'), 300)) AS details,
       json_build_object('queryid', q.queryid, 'calls', q.calls,
                         'mean_ms', round(q.mean_ms, 3), 'stddev_ms', round(q.stddev_ms, 3),
                         'stddev_multiple', round(q.stddev_ms / nullif(q.mean_ms, 0), 2),
                         'threshold_multiple', :'pg_qry_013_stddev_multiple'::numeric,
                         'total_ms', round(q.total_ms, 2),
                         'rows_per_call', round(q.rows::numeric / nullif(q.calls, 0), 2),
                         'plan_cache_mode', current_setting('plan_cache_mode'),
                         'query', left(regexp_replace(q.query, '\s+', ' ', 'g'), 300))::text AS evidence_json,
       'low'::text AS confidence
FROM q CROSS JOIN tot t
WHERE q.calls >= :'pg_qry_013_min_calls'::bigint
  AND q.mean_ms >= :'pg_qry_013_min_mean_ms'::numeric
  AND q.stddev_ms >= :'pg_qry_013_stddev_multiple'::numeric * q.mean_ms
ORDER BY q.total_ms DESC
LIMIT :'pg_qry_013_top_n'::int;
\endif
\echo '@@END PG-QRY-013'

-- ======== PG-QRY-016  P150  High-frequency statements returning almost no rows ========
\echo '@@CHECK PG-QRY-016'
-- check: PG-QRY-016
-- title: High-frequency statements returning almost no rows
-- priority: 150
-- scope: query
-- cost: 1
-- thresholds: min_calls, rows_per_call, top_n
\set ON_ERROR_STOP off
SELECT (to_regclass('pg_stat_statements') IS NOT NULL) AS pg_qry_016_pgss \gset
\if :pg_qry_016_pgss
SELECT EXISTS (SELECT 1 FROM pg_attribute
               WHERE attrelid = to_regclass('pg_stat_statements')
                 AND attname = 'total_exec_time' AND NOT attisdropped) AS pg_qry_016_v18 \gset
WITH q AS (
\if :pg_qry_016_v18
  SELECT queryid, query, calls, rows,
         total_exec_time::numeric AS total_ms, mean_exec_time::numeric AS mean_ms,
         stddev_exec_time::numeric AS stddev_ms,
         shared_blks_read, shared_blks_hit, temp_blks_read, temp_blks_written, userid
  FROM pg_stat_statements WHERE dbid = (SELECT oid FROM pg_database WHERE datname = current_database())
\else
  SELECT queryid, query, calls, rows,
         total_time::numeric AS total_ms, mean_time::numeric AS mean_ms,
         stddev_time::numeric AS stddev_ms,
         shared_blks_read, shared_blks_hit, temp_blks_read, temp_blks_written, userid
  FROM pg_stat_statements WHERE dbid = (SELECT oid FROM pg_database WHERE datname = current_database())
\endif
),
tot AS (SELECT sum(total_ms) AS all_ms, sum(calls) AS all_calls FROM q)

SELECT 'PG-QRY-016'::text AS check_id,
       'query'::text      AS scope,
       ('queryid:' || q.queryid::text)::text AS object,
       format('This statement has been executed %s times (threshold %s) and returned %s rows in total: %s rows per call (threshold %s). Total execution time %s ms, mean %s ms - individually trivial, collectively %s%% of all recorded execution time on this database, plus one round trip and one snapshot each. This shape is a polling loop, a health check, or an existence test in application code that could be cached, batched, or replaced by a notification. Statement: %s',
              to_char(q.calls, 'FM999,999,999,999'),
              to_char(:'pg_qry_016_min_calls'::bigint, 'FM999,999,999,999'),
              to_char(q.rows, 'FM999,999,999,999'),
              round(q.rows::numeric / nullif(q.calls, 0), 4)::text,
              :'pg_qry_016_rows_per_call'::text,
              to_char(round(q.total_ms), 'FM999,999,999,999'),
              round(q.mean_ms, 3)::text,
              round(100.0 * q.total_ms / nullif(t.all_ms, 0), 1)::text,
              left(regexp_replace(q.query, '\s+', ' ', 'g'), 300)) AS details,
       json_build_object('queryid', q.queryid, 'calls', q.calls, 'rows', q.rows,
                         'rows_per_call', round(q.rows::numeric / nullif(q.calls, 0), 5),
                         'threshold_calls', :'pg_qry_016_min_calls'::bigint,
                         'threshold_rows_per_call', :'pg_qry_016_rows_per_call'::numeric,
                         'total_ms', round(q.total_ms, 2), 'mean_ms', round(q.mean_ms, 4),
                         'pct_of_total_time', round(100.0 * q.total_ms / nullif(t.all_ms, 0), 2),
                         'query', left(regexp_replace(q.query, '\s+', ' ', 'g'), 300))::text AS evidence_json,
       'medium'::text AS confidence
FROM q CROSS JOIN tot t
WHERE q.calls >= :'pg_qry_016_min_calls'::bigint
  AND q.rows::numeric / nullif(q.calls, 0) < :'pg_qry_016_rows_per_call'::numeric
ORDER BY q.calls DESC
LIMIT :'pg_qry_016_top_n'::int;
\endif
\echo '@@END PG-QRY-016'

-- ======== PG-SCHEMA-003  P150  Tables without a primary key or unique index ========
\echo '@@CHECK PG-SCHEMA-003'
-- check: PG-SCHEMA-003
-- title: Tables without a primary key or unique index
-- priority: 150
-- scope: relation
-- cost: 1
-- thresholds: top_n
SELECT 'PG-SCHEMA-003'::text AS check_id,
       'relation'::text      AS scope,
       format('%I.%I.%I', current_database(), n.nspname, c.relname)::text AS object,
       format('Table %s.%s has no primary key and no valid unique index. Size %s, %s estimated rows, %s index(es). Without one: logical replication cannot replicate UPDATE or DELETE from it (PG-REPL-013 fires if it is published), there is no way to address a single row from outside the database, duplicates cannot be prevented or found cheaply, and most ORMs and CDC tools degrade or refuse. This is P150 because a table can legitimately be an append-only log; it is worth confirming that this one is.',
              n.nspname, c.relname,
              pg_size_pretty(pg_total_relation_size(c.oid)),
              to_char(greatest(c.reltuples, 0)::bigint, 'FM999,999,999,999'),
              (SELECT count(*) FROM pg_index i WHERE i.indrelid = c.oid)) AS details,
       json_build_object('schema', n.nspname, 'table', c.relname,
                         'total_bytes', pg_total_relation_size(c.oid),
                         'reltuples', greatest(c.reltuples, 0)::bigint,
                         'index_count', (SELECT count(*) FROM pg_index i WHERE i.indrelid = c.oid),
                         'relreplident', c.relreplident::text,
                         'is_published', EXISTS (SELECT 1 FROM pg_publication_tables pt
                                                 WHERE pt.schemaname = n.nspname AND pt.tablename = c.relname))::text AS evidence_json,
       'high'::text AS confidence
FROM pg_class c
JOIN pg_namespace n ON n.oid = c.relnamespace
WHERE c.relkind IN ('r', 'p')
  AND n.nspname NOT IN ('pg_catalog', 'information_schema', 'pg_toast')
  AND NOT EXISTS (SELECT 1 FROM pg_index i
                  WHERE i.indrelid = c.oid AND i.indisvalid AND (i.indisprimary OR i.indisunique))
  AND NOT EXISTS (SELECT 1 FROM pg_inherits inh WHERE inh.inhrelid = c.oid)
ORDER BY pg_total_relation_size(c.oid) DESC
LIMIT :'pg_schema_003_top_n'::int;
\echo '@@END PG-SCHEMA-003'

-- ======== PG-SCHEMA-004  P150  REPLICA IDENTITY FULL on published tables ========
SELECT (current_setting('server_version_num')::int >= 100000 AND NOT pg_is_in_recovery()) AS gate_pg_schema_004 \gset
\if :gate_pg_schema_004
\echo '@@CHECK PG-SCHEMA-004'
-- check: PG-SCHEMA-004
-- title: REPLICA IDENTITY FULL on published tables
-- priority: 150
-- scope: relation
-- cost: 1
-- min_version: 10
-- run_on: primary
SELECT 'PG-SCHEMA-004'::text AS check_id,
       'relation'::text      AS scope,
       format('%I.%I.%I', current_database(), pt.schemaname, pt.tablename)::text AS object,
       format('Table %s.%s is published by %s with REPLICA IDENTITY FULL. Every UPDATE and DELETE writes the complete old row into WAL, not just the key, so WAL volume scales with row width rather than with the change; and the subscriber matches rows by comparing every column, which is a sequential scan per change unless it has an index that happens to help. Size %s, %s estimated rows, %s writes since the statistics reset. If the table has a primary key or a unique, non-partial, NOT NULL index, REPLICA IDENTITY DEFAULT or USING INDEX is both smaller and faster.',
              pt.schemaname, pt.tablename, pt.pubname,
              pg_size_pretty(pg_total_relation_size(c.oid)),
              to_char(greatest(c.reltuples, 0)::bigint, 'FM999,999,999,999'),
              to_char(coalesce(t.n_tup_upd + t.n_tup_del, 0), 'FM999,999,999,999')) AS details,
       json_build_object('schema', pt.schemaname, 'table', pt.tablename, 'publication', pt.pubname,
                         'relreplident', c.relreplident::text,
                         'total_bytes', pg_total_relation_size(c.oid),
                         'reltuples', greatest(c.reltuples, 0)::bigint,
                         'updates_and_deletes', coalesce(t.n_tup_upd + t.n_tup_del, 0),
                         'has_primary_key', EXISTS (SELECT 1 FROM pg_index i
                                                    WHERE i.indrelid = c.oid AND i.indisprimary AND i.indisvalid))::text AS evidence_json,
       'high'::text AS confidence
FROM pg_publication_tables pt
JOIN pg_namespace n ON n.nspname = pt.schemaname
JOIN pg_class c     ON c.relname = pt.tablename AND c.relnamespace = n.oid
LEFT JOIN pg_stat_user_tables t ON t.relid = c.oid
WHERE c.relreplident = 'f'
ORDER BY pg_total_relation_size(c.oid) DESC;
\echo '@@END PG-SCHEMA-004'
\else
\echo '@@SKIP PG-SCHEMA-004 needs PostgreSQL 10 or newer; primary only'
\endif

-- ======== PG-SCHEMA-007  P150  Partitioned table with more than 1,000 partitions ========
SELECT (current_setting('server_version_num')::int >= 100000) AS gate_pg_schema_007 \gset
\if :gate_pg_schema_007
\echo '@@CHECK PG-SCHEMA-007'
-- check: PG-SCHEMA-007
-- title: Partitioned table with more than 1,000 partitions
-- priority: 150
-- scope: relation
-- cost: 1
-- min_version: 10
-- thresholds: max_partitions
SELECT 'PG-SCHEMA-007'::text AS check_id,
       'relation'::text      AS scope,
       format('%I.%I.%I', current_database(), n.nspname, c.relname)::text AS object,
       format('Partitioned table %s.%s has %s direct partitions (threshold %s), totalling %s. The planner takes a lock on every partition it cannot prune away, and it does that per query: with this many children, planning time and lock-manager traffic become visible on short queries even when execution is fast. Queries that cannot prune - anything with a non-constant partition key predicate, or a prepared generic plan - touch all of them. Consider a coarser partition interval, or sub-partitioning so pruning happens in two cheap steps.',
              n.nspname, c.relname, cnt.n, :'pg_schema_007_max_partitions'::text,
              pg_size_pretty(cnt.total_bytes)) AS details,
       json_build_object('schema', n.nspname, 'table', c.relname,
                         'partition_count', cnt.n, 'total_bytes', cnt.total_bytes,
                         'partition_strategy', p.partstrat::text,
                         'threshold', :'pg_schema_007_max_partitions'::int)::text AS evidence_json,
       'high'::text AS confidence
FROM pg_class c
JOIN pg_namespace n           ON n.oid = c.relnamespace
JOIN pg_partitioned_table p   ON p.partrelid = c.oid
CROSS JOIN LATERAL (
  SELECT count(*) AS n, coalesce(sum(pg_total_relation_size(i.inhrelid)), 0) AS total_bytes
  FROM pg_inherits i WHERE i.inhparent = c.oid
) cnt
WHERE n.nspname NOT IN ('pg_catalog', 'information_schema')
  AND cnt.n >= :'pg_schema_007_max_partitions'::int
ORDER BY cnt.n DESC;
\echo '@@END PG-SCHEMA-007'
\else
\echo '@@SKIP PG-SCHEMA-007 needs PostgreSQL 10 or newer'
\endif

-- ======== PG-SCHEMA-009  P150  Triggers on high-write tables ========
\echo '@@CHECK PG-SCHEMA-009'
-- check: PG-SCHEMA-009
-- title: Triggers on high-write tables
-- priority: 150
-- scope: relation
-- cost: 1
-- thresholds: min_writes
SELECT 'PG-SCHEMA-009'::text AS check_id,
       'relation'::text      AS scope,
       format('%I.%I.%I', current_database(), t.schemaname, t.relname)::text AS object,
       format('Table %s.%s has taken %s writes since the statistics reset (threshold %s) and carries %s user trigger(s): %s. Trigger work is invisible in the statement''s own timing and in most application metrics, so a slow trigger looks like a slow INSERT. Row-level triggers also disable the fast paths for COPY and multi-row INSERT. This is informational: it tells you where to look first when write latency on this table does not match the statement.',
              t.schemaname, t.relname,
              to_char(t.n_tup_ins + t.n_tup_upd + t.n_tup_del, 'FM999,999,999,999'),
              to_char(:'pg_schema_009_min_writes'::bigint, 'FM999,999,999,999'),
              g.n, g.names) AS details,
       json_build_object('schema', t.schemaname, 'table', t.relname,
                         'writes', t.n_tup_ins + t.n_tup_upd + t.n_tup_del,
                         'trigger_count', g.n, 'triggers', g.names,
                         'threshold_writes', :'pg_schema_009_min_writes'::bigint)::text AS evidence_json,
       'high'::text AS confidence
FROM pg_stat_user_tables t
CROSS JOIN LATERAL (
  SELECT count(*) AS n,
         string_agg(format('%s (%s)', tg.tgname, p.proname), ', ' ORDER BY tg.tgname) AS names
  FROM pg_trigger tg JOIN pg_proc p ON p.oid = tg.tgfoid
  WHERE tg.tgrelid = t.relid AND NOT tg.tgisinternal
) g
WHERE g.n > 0
  AND t.n_tup_ins + t.n_tup_upd + t.n_tup_del >= :'pg_schema_009_min_writes'::bigint
ORDER BY t.n_tup_ins + t.n_tup_upd + t.n_tup_del DESC;
\echo '@@END PG-SCHEMA-009'

-- ======== PG-SCHEMA-011  P150  Unpopulated materialized view ========
\echo '@@CHECK PG-SCHEMA-011'
-- check: PG-SCHEMA-011
-- title: Unpopulated materialized view
-- priority: 150
-- scope: relation
-- cost: 1
SELECT 'PG-SCHEMA-011'::text AS check_id,
       'relation'::text      AS scope,
       format('%I.%I.%I', current_database(), n.nspname, c.relname)::text AS object,
       format('Materialized view %s.%s was created WITH NO DATA and has never been refreshed. Any query against it fails immediately with "materialized view %s has not been populated". Owner %s, %s index(es) defined on it. Fix with REFRESH MATERIALIZED VIEW %s.%s - which is a write, and takes an ACCESS EXCLUSIVE lock unless it is refreshed CONCURRENTLY, which in turn needs a unique index.',
              n.nspname, c.relname, c.relname,
              pg_get_userbyid(c.relowner),
              (SELECT count(*) FROM pg_index i WHERE i.indrelid = c.oid),
              quote_ident(n.nspname), quote_ident(c.relname)) AS details,
       json_build_object('schema', n.nspname, 'matview', c.relname,
                         'owner', pg_get_userbyid(c.relowner),
                         'relispopulated', c.relispopulated,
                         'index_count', (SELECT count(*) FROM pg_index i WHERE i.indrelid = c.oid),
                         'has_unique_index', EXISTS (SELECT 1 FROM pg_index i
                                                     WHERE i.indrelid = c.oid AND i.indisunique))::text AS evidence_json,
       'high'::text AS confidence
FROM pg_class c
JOIN pg_namespace n ON n.oid = c.relnamespace
WHERE c.relkind = 'm' AND NOT c.relispopulated
ORDER BY n.nspname, c.relname;
\echo '@@END PG-SCHEMA-011'

-- ======== PG-SEC-016  P150  User tables readable by PUBLIC ========
\echo '@@CHECK PG-SEC-016'
-- check: PG-SEC-016
-- title: User tables readable by PUBLIC
-- priority: 150
-- scope: relation
-- cost: 1
SELECT 'PG-SEC-016'::text AS check_id,
       'relation'::text  AS scope,
       format('%I.%I.%I', current_database(), n.nspname, c.relname)::text AS object,
       format('%s %s.%s grants %s to PUBLIC. Every role that can connect to database %s holds those privileges on it, including roles created later and roles that were only meant to read something else. Size %s, %s estimated rows. Full ACL: %s. Fix with REVOKE %s ON %s.%s FROM PUBLIC, after checking which roles were relying on the PUBLIC grant.',
              CASE c.relkind WHEN 'r' THEN 'Table' WHEN 'p' THEN 'Partitioned table'
                             WHEN 'm' THEN 'Materialized view' WHEN 'v' THEN 'View'
                             WHEN 'f' THEN 'Foreign table' WHEN 'S' THEN 'Sequence' ELSE 'Relation' END,
              n.nspname, c.relname, g.privs, current_database(),
              pg_size_pretty(pg_total_relation_size(c.oid)),
              to_char(greatest(c.reltuples, 0)::bigint, 'FM999,999,999,999'),
              array_to_string(c.relacl, ', '),
              g.privs, quote_ident(n.nspname), quote_ident(c.relname)) AS details,
       json_build_object('schema', n.nspname, 'relname', c.relname, 'relkind', c.relkind,
                         'public_privileges', g.privs,
                         'relacl', array_to_string(c.relacl, ';'),
                         'owner', pg_get_userbyid(c.relowner),
                         'total_bytes', pg_total_relation_size(c.oid),
                         'reltuples', greatest(c.reltuples, 0)::bigint)::text AS evidence_json,
       'high'::text AS confidence
FROM pg_class c
JOIN pg_namespace n ON n.oid = c.relnamespace
CROSS JOIN LATERAL (
  SELECT string_agg(DISTINCT a.privilege_type, ', ' ORDER BY a.privilege_type) AS privs
  FROM aclexplode(c.relacl) a
  WHERE a.grantee = 0 AND a.privilege_type IN ('SELECT', 'REFERENCES')
) g
WHERE c.relkind IN ('r', 'p', 'm', 'v', 'f', 'S')
  AND n.nspname NOT IN ('pg_catalog', 'information_schema', 'pg_toast')
  AND g.privs IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM aclexplode(c.relacl) a2
                  WHERE a2.grantee = 0
                    AND a2.privilege_type IN ('INSERT', 'UPDATE', 'DELETE', 'TRUNCATE'))
ORDER BY pg_total_relation_size(c.oid) DESC;
\echo '@@END PG-SEC-016'

-- ======== PG-VAC-012  P150  Low HOT-update ratio on update-heavy tables ========
\echo '@@CHECK PG-VAC-012'
-- check: PG-VAC-012
-- title: Low HOT-update ratio on update-heavy tables
-- priority: 150
-- scope: relation
-- cost: 1
-- thresholds: min_updates, hot_ratio
SELECT 'PG-VAC-012'::text AS check_id,
       'relation'::text   AS scope,
       format('%I.%I.%I', current_database(), t.schemaname, t.relname)::text AS object,
       format('%s updates since the statistics reset, of which %s (%s%%, threshold %s%%) were heap-only. fillfactor is at the default 100, so an update that does not fit on the page must write a new tuple in a new page and add an entry to every index. Size %s, %s indexes. A lower fillfactor helps only if the updated columns are not themselves indexed, which cannot be determined from the catalog.',
              to_char(t.n_tup_upd, 'FM999,999,999,999'),
              to_char(t.n_tup_hot_upd, 'FM999,999,999,999'),
              round(100.0 * t.n_tup_hot_upd / nullif(t.n_tup_upd, 0), 1)::text,
              round(100 * :'pg_vac_012_hot_ratio'::numeric)::text,
              pg_size_pretty(pg_total_relation_size(t.relid)),
              (SELECT count(*) FROM pg_index i WHERE i.indrelid = t.relid)) AS details,
       json_build_object('n_tup_upd', t.n_tup_upd, 'n_tup_hot_upd', t.n_tup_hot_upd,
                         'hot_ratio', round(t.n_tup_hot_upd::numeric / nullif(t.n_tup_upd, 0), 4),
                         'threshold_ratio', :'pg_vac_012_hot_ratio'::numeric,
                         'total_bytes', pg_total_relation_size(t.relid),
                         'index_count', (SELECT count(*) FROM pg_index i WHERE i.indrelid = t.relid))::text AS evidence_json,
       'low'::text AS confidence
FROM pg_stat_user_tables t
JOIN pg_class c ON c.oid = t.relid
WHERE t.n_tup_upd >= :'pg_vac_012_min_updates'::bigint
  AND t.n_tup_hot_upd::numeric / nullif(t.n_tup_upd, 0) < :'pg_vac_012_hot_ratio'::numeric
  AND coalesce(array_to_string(c.reloptions, ' '), '') !~ 'fillfactor'
ORDER BY t.n_tup_upd DESC
LIMIT 10;
\echo '@@END PG-VAC-012'

\echo '@@RUN-END fast database'
